function _applyLogoEverywhere(){
  const logo=_getCompanyLogo();
  const sbImg=document.getElementById('sb-logo-img');
  const sbBrand=document.querySelector('.sb-brand');
  const sbName=document.getElementById('sb-company-name');
  const sbIcon=document.getElementById('sb-logo-icon');
  if(sbImg){sbImg.src=logo||'';sbImg.style.display=logo?'block':'none';}
  if(sbIcon)sbIcon.style.display=logo?'none':'';
  if(sbBrand)sbBrand.style.display=logo?'none':'';
  if(sbName){
    const name=currentCompany?.name||localStorage.getItem('taxflow_company_name')||'';
    sbName.textContent=name;
    sbName.style.display=name?'block':'none';
  }
  const prevImg=document.getElementById('co-logo-preview-img');
  const initEl=document.getElementById('co-logo-initials');
  const rmBtn=document.getElementById('co-logo-remove');
  if(prevImg){prevImg.src=logo||'';prevImg.style.display=logo?'block':'none';}
  if(initEl)initEl.style.display=logo?'none':'';
  if(rmBtn)rmBtn.style.display=logo?'':'none';
}

async function _saveLogoToDb(dataUrl){
  try{
    await authenticatedFetch(`${apiBaseUrl()}/companies/current`,{
      method:'PUT',
      body:JSON.stringify({logo:dataUrl||null})
    });
  }catch(e){
    console.warn('Logo DB save failed:',e);
  }
}

function handleLogoUpload(input){
  const file=input.files?.[0];
  if(!file)return;
  if(file.size>2097152){toast('Logo must be under 2 MB','warn');return;}
  const reader=new FileReader();
  reader.onload=async e=>{
    const dataUrl=e.target.result;
    localStorage.setItem(_LOGO_KEY,dataUrl);
    _applyLogoEverywhere();
    await _saveLogoToDb(dataUrl);
    toast('Company logo saved','ok');
    updateInvoiceLayoutPreview?.();
    updateQuotationLayoutPreview?.();
  };
  reader.readAsDataURL(file);
}

async function removeLogo(){
  localStorage.removeItem(_LOGO_KEY);
  const f=document.getElementById('co-logo-file');
  if(f)f.value='';
  _applyLogoEverywhere();
  await _saveLogoToDb(null);
  toast('Logo removed','ok');
  updateInvoiceLayoutPreview?.();
  updateQuotationLayoutPreview?.();
}

function applyCompanyToUi(company){
  if(!company)return;
  currentCompany=company;
  // initInvoiceLayouts() (app init) can run before this — the async company
  // fetch isn't guaranteed to resolve first — so a freshly-created Saudi
  // company's ZATCA QR default may have been computed against a still-empty
  // currentCompany and cached to localStorage as the wrong 'invoice_url'.
  // Only touches the still-pristine, never-saved default (see
  // _invoiceLayoutsPristine's declaration) — a layout the user has actually
  // edited/saved is never overwritten here.
  if(_invoiceLayoutsPristine&&Array.isArray(_invoiceLayouts)&&_invoiceLayouts.length){
    const wantedQrType=company.country==='Saudi Arabia'?'zatca_qr':'invoice_url';
    const defaultLayout=_invoiceLayouts.find(l=>l.isDefault);
    if(defaultLayout&&defaultLayout.qrCodeType!==wantedQrType&&(defaultLayout.qrCodeType==='invoice_url'||defaultLayout.qrCodeType==='zatca_qr')){
      defaultLayout.qrCodeType=wantedQrType;
      if(_activeLayoutId===defaultLayout.id){
        const qrField=document.getElementById('inv-layout-qr-type');
        if(qrField)qrField.value=wantedQrType;
      }
      _ilSave();
    }
  }
  const set=(id,val)=>{const el=document.getElementById(id);if(el)el.value=val||'';};
  // Core fields
  set('set-company-name',company.name);
  set('set-company-trn',company.trn);
  set('trn',company.trn);
  set('tax-trn',company.trn);
  set('tax-fta-user',company.fta_username);
  set('co-fta-user',company.fta_username);
  set('co-fta-user-reg',company.fta_username);
  // Settings page fields
  set('set-company-trade-name',company.trade_name);
  set('set-company-license',company.trade_license_no);
  set('set-company-issue-date',company.trade_license_issue_date);
  set('set-company-license-expiry',company.trade_license_expiry);
  set('set-company-activity',company.business_activity);
  set('set-company-structure',company.legal_structure);
  set('set-company-emirate',company.emirate);
  set('set-company-freezone',company.free_zone||'Not Applicable');
  set('set-company-biz-type',company.business_type);
  set('set-company-address',company.address);
  set('set-company-pobox',company.po_box);
  set('set-company-phone',company.phone);
  set('set-company-website',company.website);
  set('set-company-currency',company.currency||'AED');
  const vatRateNum=company.vat_rate!=null?Number(company.vat_rate):5;
  const vatRateEl=document.getElementById('set-company-vat-rate');
  if(vatRateEl)vatRateEl.value=vatRateNum;
  const taxVatDisplay=document.getElementById('tax-vat-rate-display');
  if(taxVatDisplay)taxVatDisplay.value=vatRateNum+'%';
  window.COMPANY_CURRENCY=company.currency||'AED';
  window.COMPANY_VAT_RATE=vatRateNum;
  syncCurrencyHeaderLabels();
  // Create Invoice tab's totals default to a static "AED 0.00" in the HTML
  // (index.html) until the user edits a line item — refresh them here too,
  // so a non-AED company doesn't see the wrong currency on a freshly
  // opened, untouched invoice form.
  if(document.getElementById('subtotal'))calcLine();
  if(document.getElementById('pay-period'))populatePayrollPeriods();
  // Company registration page fields
  set('co-name',company.name);
  set('co-trade-name',company.trade_name);
  set('co-trade-license',company.trade_license_no);
  set('co-issue-date',company.trade_license_issue_date);
  set('co-license-expiry',company.trade_license_expiry);
  set('co-freezone',company.free_zone||'Not Applicable');
  set('co-activity',company.business_activity);
  set('co-structure',company.legal_structure);
  set('co-emirate',company.emirate);
  set('co-biz-type',company.business_type);
  set('co-address',company.address);
  set('co-pobox',company.po_box);
  set('co-phone',company.phone);
  set('co-website',company.website);
  // Invoice layout company name + address (if not user-overridden)
  const layoutCompany=document.getElementById('inv-layout-company');
  if(layoutCompany&&!layoutCompany.dataset.userEdited)setFieldValue(layoutCompany,company.name||'');
  const layoutAddr=document.getElementById('inv-layout-address');
  if(layoutAddr&&!layoutAddr.dataset.userEdited&&company.address)setFieldValue(layoutAddr,company.address);
  // Logo + company name sync
  if(company.logo){
    localStorage.setItem(_LOGO_KEY,company.logo);
  } else if(!company.logo&&localStorage.getItem(_LOGO_KEY)){
    localStorage.removeItem(_LOGO_KEY);
  }
  if(company.name)localStorage.setItem('taxflow_company_name',company.name);
  _applyLogoEverywhere();
  updateInvoiceLayoutPreview?.();
  renderBusinessLocationRows();
  applyDeptsBranchesFromCompany(company);
  const essLinkEl=document.getElementById('ess-portal-link');
  if(essLinkEl&&company.id)essLinkEl.textContent=`${window.location.origin}/ess?c=${company.id}`;
  applyModulePermissionNav(company.modules_enabled);
}

// Superadmin's per-company "Module Permissions" (set at company creation or
// via the Modules button on the superadmin company list) — hides sidebar
// entries for modules this company hasn't been granted. `null`/undefined
// means "not restricted" (matches the backend's own fallback for companies
// that predate this column) so this never locks an existing company out.
// Mirrors the same hide-by-data-module pattern already used for HRMS
// per-employee RBAC nav (applyHrmsPermissionNav in hrms.html) — but that's
// a DIFFERENT, non-overlapping data-module vocabulary on the SAME ".sb"
// sidebar class in hrms.html, so this must never run there: it would find
// zero matches for any HRMS module key and hide the entire HRMS sidebar.
// Keep in sync with ALL_MODULES in backend/app/routers/superadmin.py and
// MODULE_DEFS in superadmin.html's Modules grid — same 17 keys, just the
// friendly labels needed for the read-only summary on the company's own
// Settings > Company Registration tab (renderModuleAccessCard below).
const ALL_MODULE_DEFS=[
  {key:'sales',label:'Sales & Invoices'},
  {key:'quotations',label:'Quotations'},
  {key:'pos',label:'Point of Sale'},
  {key:'purchase',label:'Purchases'},
  {key:'inventory',label:'Inventory'},
  {key:'expense',label:'Expenses'},
  {key:'bank',label:'Bank & Payments'},
  {key:'accounting',label:'Accounting'},
  {key:'corporate',label:'Corporate Accounting'},
  {key:'reports',label:'Reports'},
  {key:'hrms',label:'HRMS Portal'},
  {key:'ess',label:'ESS Portal'},
  {key:'notifications',label:'Notifications'},
  {key:'expert',label:'Expert Review'},
  {key:'exception',label:'Exception Center'},
  {key:'ai',label:'AI Features'},
  {key:'settings',label:'Company & Settings'},
];

function renderModuleAccessCard(allowedOrNull){
  const wrap=document.getElementById('module-access-grid');
  if(!wrap)return;
  wrap.innerHTML=ALL_MODULE_DEFS.map(m=>{
    const on=!allowedOrNull||allowedOrNull.has(m.key);
    return `<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;background:var(--surface2)">
      <span style="font-size:12.5px">${escapeHtml(m.label)}</span>
      <span class="b ${on?'b-g':'b-r'}" style="font-size:10.5px;flex-shrink:0">${on?'Enabled':'Disabled'}</span>
    </div>`;
  }).join('');
}

window.COMPANY_ALLOWED_MODULES=null;
function applyModulePermissionNav(modulesEnabled){
  // Branch Login Phase 1: window.COMPANY_ALLOWED_MODULES must be set even
  // on hrms.html (HRMS_STANDALONE) — the Branch modal's module grid
  // (buildBranchModGrid) and the Role modal's company-inheritance filter
  // both read it there. The early return below still skips the
  // index.html-only sidebar DOM manipulation, which doesn't apply on this
  // page and would no-op harmlessly anyway (no .sb/[data-module] elements
  // exist in hrms.html's DOM).
  window.COMPANY_ALLOWED_MODULES=Array.isArray(modulesEnabled)?new Set(modulesEnabled):null;
  if(window.HRMS_STANDALONE)return;
  if(!Array.isArray(modulesEnabled)){
    document.querySelectorAll('.sb .nav[data-module]').forEach(n=>n.classList.remove('hidden'));
    document.querySelectorAll('[data-module-gate]').forEach(n=>n.classList.remove('hidden'));
    renderModuleAccessCard(null);
    return;
  }
  const allowed=window.COMPANY_ALLOWED_MODULES;
  document.querySelectorAll('.sb .nav[data-module]').forEach(n=>{
    n.classList.toggle('hidden',!allowed.has(n.dataset.module));
  });
  // Module-gated entry points outside the sidebar (topbar buttons, quick
  // actions, settings tabs) — e.g. AI Assistant, Exception Center — that
  // don't fit the .sb .nav[data-module] pattern above.
  document.querySelectorAll('[data-module-gate]').forEach(n=>{
    n.classList.toggle('hidden',!allowed.has(n.dataset.moduleGate));
  });
  renderModuleAccessCard(allowed);
}

function _moduleNavAllowed(page){
  if(!window.COMPANY_ALLOWED_MODULES)return true;
  const nav=document.querySelector(`.sb .nav[data-module="${page}"]`)||document.querySelector(`[data-module-gate="${page}"]`);
  if(!nav)return true; // not a module-gated destination (dashboard, settings, etc.)
  return window.COMPANY_ALLOWED_MODULES.has(page);
}

// Sidebar module gating for an Employee/branch-login session on index.html
// (Main Dashboard Access phase) — mirrors applyHrmsPermissionNav()'s exact
// mechanism in hrms.html (whoami -> filter permissions ending ":view" ->
// module set -> hide non-allowed .sb .nav[data-module] entries) but writes
// to its OWN distinct global, window.MAIN_ALLOWED_MODULES, rather than
// reusing window.HRMS_ALLOWED_MODULES: that one is documented as
// hrms.html-specific and consumed by _hrmsNavAllowed(), which is already
// hard-wired off on index.html (`if(!window.HRMS_STANDALONE...)return
// true`) — sharing one mutable global across two pages that load this same
// bundle risks stale-value bugs for no benefit. Composes safely with
// applyModulePermissionNav()'s classList('hidden') company-level gate on
// the exact same elements: independent CSS-hiding mechanisms (style.display
// here, classList there), so a nav item is visible only when NEITHER has
// hidden it — the desired "company module enabled AND role permits"
// semantics, with zero coordination code.
async function applyMainDashboardPermissionNav(){
  try{
    const token=localStorage.getItem('taxflow_token');
    if(!token)return;
    const resp=await fetch(apiBaseUrl()+'/auth/whoami',{headers:{Authorization:'Bearer '+token}});
    if(!resp||!resp.ok)return;
    const who=await resp.json();
    applyBranchSwitcherFromWhoami(who);
    // applyRoleBasedNav() (the equivalent call for a User/admin session) is
    // never invoked for an employee/branch principal_kind (see initApp()),
    // so this is the only place a Branch-impersonation session's banner can
    // render — /auth/whoami is what a branch token can actually call,
    // unlike the User-only /auth/me applyRoleBasedNav() uses.
    renderImpersonationBanner(who.impersonated_by,{name:currentCompany?.name||''},who.display_name);
    if(who.is_admin){window.MAIN_ALLOWED_MODULES=null;return;}
    const allowed=new Set((who.permissions||[]).filter(p=>p.endsWith(':view')).map(p=>p.split(':')[0]));
    window.MAIN_ALLOWED_MODULES=allowed;
    document.querySelectorAll('.sb .nav[data-module]').forEach(nav=>{
      const mod=nav.getAttribute('data-module');
      nav.style.display=allowed.has(mod)?'':'none';
    });
    // The sidebar's "HRMS" link (data-module="hrms") has no catalog entry —
    // there is no blanket "hrms:view" permission key, HR access is granted
    // per-module (employees:view, leave:view, etc.) same as it always has
    // been. Show it if the employee's role grants ANY HR module :view
    // permission, rather than leaving it permanently hidden the way it
    // effectively was before this phase (a hidden nav item the generic loop
    // above would never unhide, since "hrms" never appears in `allowed`).
    const hrmsNav=document.querySelector('.sb .nav[data-module="hrms"]');
    if(hrmsNav){
      const hasAnyHrAccess=[...allowed].some(m=>['employees','leave','attendance','rota','overtime','loans','recruitment','payroll','hr','hr_settings','hr_workflow','performance'].includes(m));
      hrmsNav.style.display=hasAnyHrAccess?'':'none';
    }
  }catch(e){
    console.warn('[MainDashboardPermissionNav]',e);
  }
}

// Direct-navigation guard, sibling of _hrmsNavAllowed()/_moduleNavAllowed()
// above but for the new per-role main-dashboard gate — UI politeness only,
// the real boundary is the backend 403 on every underlying API call (see
// require_principal_permission() usage across accounting.py/
// corporate_accounting.py/tax.py/reports.py).
function _mainDashboardNavAllowed(page){
  if(window.HRMS_STANDALONE||!window.MAIN_ALLOWED_MODULES)return true;
  const nav=document.querySelector(`.sb .nav[data-module="${page}"]`);
  if(!nav)return true; // not a role-gated destination (dashboard, settings, etc.)
  return window.MAIN_ALLOWED_MODULES.has(page);
}
function _mainDashboardBlockNav(){
  toast("You don't have access to this module — contact your administrator",'warn');
}

function copyEssPortalLink(){
  const el=document.getElementById('ess-portal-link');
  const link=el?.textContent||'';
  if(!link){toast('Company not loaded yet — try again in a moment','warn');return;}
  if(navigator.clipboard&&window.isSecureContext){
    navigator.clipboard.writeText(link).then(()=>toast('ESS portal link copied!','ok')).catch(()=>_copyFallback(link,'ESS portal link'));
  }else{
    _copyFallback(link,'ESS portal link');
  }
}

async function syncCompanyFromDatabase(){
  const ready=await ensureBackendSession();
  if(!ready)return null;
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/companies/current`);
    if(response.status===403){
      // A 403 here (session otherwise valid — authenticatedFetch only force-
      // logs-out on 401) covering the one case that isn't "insufficient
      // permission for this call": the company's subscription expired mid-
      // session (assert_company_active, backend/app/auth_principal.py).
      // New logins already show this clearly via login.html's existing
      // error display; this covers a tab that was already open when
      // superadmin suspended the company.
      let detail='';
      try{detail=(await response.clone().json())?.detail||'';}catch{}
      if(/subscription has expired/i.test(detail)){
        try{toast(detail,'err');}catch{}
        localStorage.removeItem('taxflow_token');
        setTimeout(()=>window.location.replace('/login'),1500);
        return null;
      }
    }
    if(!response.ok)throw new Error('Company API returned '+response.status);
    const company=await response.json();
    applyCompanyToUi(company);
    return company;
  }catch(err){
    console.warn('Company database sync failed:',err);
    return null;
  }
}

async function saveCompanySettingsToDatabase(){
  const v=id=>document.getElementById(id)?.value?.trim()||null;
  const name=v('set-company-name')||readFieldValue('Legal Company Name')||currentCompany?.name||null;
  if(!name){toast('Company name is required','warn');return;}
  const rawTrn=(v('set-company-trn')||'').replace(/\D/g,'');
  const trn=rawTrn.length===15?rawTrn:(currentCompany?.trn||null);
  const vatRateRaw=document.getElementById('set-company-vat-rate')?.value;
  const vatRate=(vatRateRaw!==''&&vatRateRaw!=null)?Number(vatRateRaw):(currentCompany?.vat_rate??5);
  const payload={
    name,
    trn,
    trade_name:v('set-company-trade-name'),
    country:currentCompany?.country||'United Arab Emirates',
    currency:v('set-company-currency')||currentCompany?.currency||'AED',
    vat_rate:vatRate,
    emirate:v('set-company-emirate'),
    business_type:v('set-company-biz-type'),
    business_activity:v('set-company-activity'),
    legal_structure:v('set-company-structure'),
    trade_license_no:v('set-company-license'),
    trade_license_issue_date:v('set-company-issue-date'),
    trade_license_expiry:v('set-company-license-expiry'),
    free_zone:v('set-company-freezone'),
    address:v('set-company-address'),
    po_box:v('set-company-pobox'),
    phone:v('set-company-phone'),
    website:v('set-company-website'),
    fta_username:v('tax-fta-user')||v('co-fta-user')||currentCompany?.fta_username||null,
  };
  const _saveUrl=`${apiBaseUrl()}/companies/current`;
  const response=await authenticatedFetch(_saveUrl,{
    method:'PUT',
    body:JSON.stringify(payload)
  });
  if(!response.ok){
    let detail='';
    try{const e=await response.clone().json();detail=e.detail||'';}catch(x){}
    throw new Error(`Company save returned ${response.status}${detail?' — '+detail:''} (url: ${response.url})`);
  }
  const company=await response.json();
  applyCompanyToUi(company);
  audit('Updated company settings',company.name,'Saved');
  return company;
}

async function saveTaxSettings(){
  const trn=(document.getElementById('tax-trn')?.value||'').replace(/\D/g,'');
  const fta_username=(document.getElementById('tax-fta-user')?.value||'').trim();
  if(trn&&trn.length!==15){toast('TRN must be exactly 15 digits','warn');return;}
  const payload={
    ...(currentCompany||{}),
    name:currentCompany?.name||'',
    trn:trn||currentCompany?.trn||null,
    fta_username:fta_username||currentCompany?.fta_username||null,
  };
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/companies/current`,{method:'PUT',body:JSON.stringify(payload)});
    if(!response.ok)throw new Error('Save failed ('+response.status+')');
    const company=await response.json();
    applyCompanyToUi(company);
    audit('Updated tax settings',company.trn||company.name,'Saved');
    toast('Tax settings saved','ok');
  }catch(err){toast('Save failed: '+err.message,'warn');}
}

async function loadUsersIntoTable(){
  const tbody=document.getElementById('user-tbody');
  if(!tbody)return;
  try{
    const resp=await authenticatedFetch(`${apiBaseUrl()}/app-data/users`);
    if(!resp.ok)throw new Error('Users API returned '+resp.status);
    const data=await resp.json();
    const users=data.users||[];
    if(!users.length){
      tbody.innerHTML='<tr><td colspan="7" style="color:var(--text3);text-align:center">No users found. Add users with the button above.</td></tr>';
      return;
    }
    tbody.innerHTML='';
    users.forEach(u=>{try{renderUserRecord({status:'Active',...u,permissions:Array.isArray(u.permissions)?u.permissions:[]});}catch(e){console.warn('[renderUserRecord]',e,u);}});
  }catch(err){
    tbody.innerHTML='<tr><td colspan="7" style="color:var(--text3);text-align:center">Could not load users.</td></tr>';
    console.warn('[loadUsersIntoTable]',err);
  }
}

async function saveCompanyRegistration(){
  const v=id=>document.getElementById(id)?.value?.trim()||null;
  const name=v('co-name')||currentCompany?.name||'';
  if(!name){toast('Company name is required','warn');return;}
  const payload={
    name,
    trn:currentCompany?.trn||null,
    trade_name:v('co-trade-name')||currentCompany?.trade_name||null,
    country:currentCompany?.country||'United Arab Emirates',
    trade_license_no:v('co-trade-license'),
    trade_license_issue_date:v('co-issue-date'),
    trade_license_expiry:v('co-license-expiry'),
    free_zone:v('co-freezone'),
    business_activity:v('co-activity'),
    legal_structure:v('co-structure'),
    emirate:v('co-emirate'),
    business_type:v('co-biz-type'),
    address:v('co-address'),
    po_box:v('co-pobox'),
    phone:v('co-phone'),
    website:v('co-website'),
  };
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/companies/current`,{method:'PUT',body:JSON.stringify(payload)});
    if(!response.ok)throw new Error('Save returned '+response.status);
    const company=await response.json();
    applyCompanyToUi(company);
    toast('Company registration saved','ok');
    audit('Saved business registration details','Company','Saved');
  }catch(err){
    toast('Save failed: '+err.message,'err');
  }
}

function setDashboardStat(label,value,delta){
  const idMap={
    'Total Revenue + VAT':['dash-revenue','dash-revenue-sub'],
    'VAT Payable':['dash-vat','dash-vat-sub'],
    'Open Invoices':['dash-open-invoices','dash-open-invoices-sub'],
    'Staff Present':['dash-staff','dash-staff-sub']
  };
  const ids=idMap[label];
  if(ids){
    const val=document.getElementById(ids[0]);
    const sub=document.getElementById(ids[1]);
    if(val)val.textContent=value;
    if(sub&&delta)sub.textContent=delta;
  }
  document.querySelectorAll('#page-dashboard .stat').forEach(stat=>{
    const title=stat.querySelector('.stat-lbl');
    if(title&&title.textContent.trim()===label){
      const val=stat.querySelector('.stat-val');
      const sub=stat.querySelector('.stat-delta');
      if(val)val.textContent=value;
      if(sub&&delta)sub.textContent=delta;
    }
  });
}

function setNavBadge(page,count,variant=''){
  const nav=[...document.querySelectorAll('.nav')].find(item=>(item.getAttribute('onclick')||'').includes(`'${page}'`));
  if(!nav)return;
  let badge=nav.querySelector('.nbadge');
  if(!badge){
    badge=document.createElement('span');
    nav.appendChild(badge);
  }
  badge.className=`nbadge ${variant}`.trim();
  badge.textContent=Number(count||0).toLocaleString('en-AE');
}

function syncSidebarCounts(data){
  // Counts removed from sidebar — only exception badge remains
  const counts=data.module_counts||data;
  const exceptionCount=Number(counts.exception_count||0);
  // Clear all nav badges
  document.querySelectorAll('.nbadge').forEach(el=>el.remove());
  // Only keep exception warning badge
  if(exceptionCount)setNavBadge('exception',exceptionCount,'warn');
}

function renderDashboardMeta(data){
  const meta=data.dashboard_meta||{};
  // The backend never actually sends dashboard_meta today, so meta.title/
  // subtitle are always undefined — caching the resolved fallback text here
  // (not just the raw meta fields) is what lets a later go('dashboard') call
  // pick up real text instead of index.html's static "Loading dashboard from
  // database" placeholder, even if this ran while the dashboard page wasn't
  // visible yet and skipped the direct DOM write below.
  META.dashboard.t=meta.title||'Dashboard';
  META.dashboard.s=meta.subtitle||'Dashboard loaded from database records';
  const dashboardVisible=document.getElementById('page-dashboard')?.classList.contains('on');
  if(dashboardVisible){
    const title=document.getElementById('ptitle');
    const sub=document.getElementById('psub');
    const arDash=_appLang==='ar'?_META_AR.dashboard:null;
    if(title)title.textContent=arDash?.t||META.dashboard.t;
    if(sub)sub.textContent=arDash?.s||META.dashboard.s;
  }
}

const REPORT_RETRY_DELAYS_MS=[400,1200]; // dashboard/summary retry backoff — see _fetchReportWithRetry()

function _reportAbortSignal(ms=15000){
  // Matches the existing _extractionAbortSignal() pattern — a hung request
  // gets cancelled-and-retried instead of leaving the UI on "Loading..."
  // indefinitely while waiting for DigitalOcean's own edge timeout.
  const controller=new AbortController();
  setTimeout(()=>controller.abort(),ms);
  return controller.signal;
}

async function _fetchReportWithRetry(url){
  // Bounded retry specifically for the two heaviest report endpoints
  // (dashboard/summary): on a 500/503/504 or a client-side timeout, retry
  // with short backoff before giving up — these are idempotent GETs, so
  // always safe to retry. The backend now serves stale cached data instead
  // of erroring whenever it can (reports.py's _cached_or_build()), so most
  // transient overload never even reaches here; this is the secondary
  // safety net for whatever still does, and often just quietly succeeds on
  // the 2nd/3rd attempt as a concurrent burst clears. Deliberately scoped
  // to these two call sites rather than added to authenticatedFetch()
  // itself, since blanket-retrying every API call (including writes) would
  // not be safe.
  let lastErr=null;
  for(let attempt=0;attempt<=REPORT_RETRY_DELAYS_MS.length;attempt++){
    try{
      const response=await authenticatedFetch(url,{signal:_reportAbortSignal()});
      if(response.ok||![500,503,504].includes(response.status))return response;
      lastErr=new Error('Report API returned '+response.status);
    }catch(err){
      lastErr=err.name==='AbortError'?new Error('Report request timed out'):err;
    }
    if(attempt<REPORT_RETRY_DELAYS_MS.length)await new Promise(r=>setTimeout(r,REPORT_RETRY_DELAYS_MS[attempt]));
  }
  throw lastErr;
}

async function syncDashboardFromDatabase(){
  const ready=await ensureBackendSession();
  if(!ready){
    setDashboardStat('Total Revenue + VAT','Login needed','Open the root app and sign in');
    setDashboardStat('VAT Payable','Login needed','No backend token found');
    setDashboardStat('Open Invoices','Login needed','Dashboard cannot read database');
    setDashboardStat('Staff Present','Login needed','Use admin@taxflowapp.com');
    return;
  }
  if(!window.__taxflowFreshDashboardLoaded)renderCachedDashboardSnapshot();
  try{
    const response=await _fetchReportWithRetry(`${apiBaseUrl()}/reports/dashboard`);
    if(!response.ok)throw new Error('Dashboard API returned '+response.status);
    const data=await response.json();
    window.__taxflowFreshDashboardLoaded=true;
    try{localStorage.setItem('taxflow_dashboard_snapshot',JSON.stringify(data));}catch{}
    if(data.company)applyCompanyToUi(data.company);
    renderDashboardMeta(data);
    syncSidebarCounts(data);
    renderFullDashboardFromDatabase(data);
    syncBranchPerformanceFromDatabase();
  }catch(err){
    console.warn('Dashboard database sync failed:',err);
    setDashboardStat('Total Revenue + VAT','—','Check backend connection');
    setDashboardStat('VAT Payable','—','Dashboard sync failed');
    setDashboardStat('Open Invoices','—','Open browser console for details');
    setDashboardStat('Staff Present','—','Retrying on next load');
    const errHtml=`<div style="font-size:12px;color:var(--text3)">Could not load data. Please refresh.</div>`;
    ['dash-recent-activity','dash-invoice-status'].forEach(id=>{
      const el=document.getElementById(id);
      if(el)el.innerHTML=errHtml;
    });
    if(!window.__taxflowFreshDashboardLoaded&&!window.__taxflowDashboardRetried){
      window.__taxflowDashboardRetried=true;
      setTimeout(()=>syncDashboardFromDatabase(),3000);
    }
  }
}

async function syncBranchPerformanceFromDatabase(){
  const list=document.getElementById('dash-branch-list');
  if(!list)return;
  try{
    const response=await authenticatedFetch(`${apiBaseUrl()}/reports/branch-performance`);
    if(!response.ok)throw new Error('Branch performance API returned '+response.status);
    const data=await response.json();
    renderBranchPerformance(data);
  }catch(err){
    console.warn('Branch performance sync failed:',err);
    list.innerHTML='<div style="font-size:12px;color:var(--text3);text-align:center;padding:16px 0">Could not load branch performance.</div>';
  }
}

// "View as branch" is an admin-only lightweight filter (no new token, no
// audit log — see viewDashboardAsBranch()/exitBranchDashboardView() below),
// distinct from Super Admin's real impersonation (superadmin.html). Gated
// on principal_kind being absent (=admin per the same convention initApp()
// uses) so a Branch Login viewing its own single row here never sees a
// button offering to switch into a branch it has no cross-branch access to.
function _isAdminPrincipal(){
  try{return !localStorage.getItem('taxflow_principal_kind');}catch{return true;}
}

// Keeps the Dashboard page header honest about which branch's data is on
// screen — "Head Office Dashboard" (META.dashboard.t) by default, or
// "<Branch> Dashboard" whenever a branch is actually the active scope,
// whether that's a genuine Branch Login/employee session (branchName from
// /auth/whoami, see applyBranchSwitcherFromWhoami()) or an admin using the
// "View as" toggle above (see renderBranchPerformance()). Only touches
// #ptitle while Dashboard is the visible page, so it can't clobber another
// page's title if a background sync fires after the user navigated away.
function _setDashboardTitle(branchName){
  const page=document.getElementById('page-dashboard');
  if(!page||!page.classList.contains('on'))return;
  const el=document.getElementById('ptitle');
  if(el)el.textContent=branchName?`${branchName} Dashboard`:(META.dashboard?.t||'Head Office Dashboard');
}

function renderBranchPerformance(data){
  const list=document.getElementById('dash-branch-list');
  if(!list)return;
  const branches=Array.isArray(data?.branches)?data.branches:[];
  const rows=[...branches];
  if(data?.unassigned)rows.push(data.unassigned);
  if(!data?.has_branches){
    list.innerHTML=`<div style="font-size:12px;color:var(--text3);text-align:center;padding:16px 4px;line-height:1.5">No branches set up yet. Add branches in Settings to see revenue and profit broken down per branch.</div>`;
    return;
  }
  if(!rows.length){
    list.innerHTML=`<div style="font-size:12px;color:var(--text3);text-align:center;padding:16px 4px;line-height:1.5">No branch-attributed sales or purchases yet.</div>`;
    return;
  }
  const canViewAs=_isAdminPrincipal();
  const activeId=window.ACTIVE_BRANCH_ID||null;
  window.__branchPerfNameById=window.__branchPerfNameById||{};
  const activeRow=activeId?rows.find(r=>r.branch_id===activeId):null;
  if(canViewAs)_setDashboardTitle(activeRow?activeRow.name:null);
  const banner=(canViewAs&&activeRow)?`<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;background:#eef2ff;border:1px solid #c7d2fe;border-radius:8px;padding:6px 10px;margin-bottom:8px;font-size:11.5px;color:#3730a3">
    <span>Viewing dashboard as <strong>${escapeHtml(activeRow.name||'branch')}</strong></span>
    <button class="btn btn-g btn-sm" style="padding:2px 8px;font-size:11px;flex-shrink:0" onclick="exitBranchDashboardView()">View All Branches</button>
  </div>`:'';
  list.innerHTML=banner+rows.map(row=>{
    const profit=Number(row.profit||0);
    const profitColor=profit>=0?'#16a34a':'#dc2626';
    const isUnassigned=row.branch_id===null||row.branch_id===undefined;
    const name=isUnassigned?'Head Office':(row.name||'Unnamed Branch');
    const pending=row.invoices_pending||{count:0,amount:'0.00'};
    const collected=row.invoices_collected||{count:0,amount:'0.00'};
    const isActive=!isUnassigned&&row.branch_id===activeId;
    if(!isUnassigned)window.__branchPerfNameById[row.branch_id]=name;
    // data-branch-id + a delegated onclick lookup (not the name inlined into
    // the attribute) — a branch name containing a quote/apostrophe inlined
    // straight into onclick="" corrupts the HTML (same bug class as the POS
    // JSON.stringify()-in-onclick issue fixed earlier).
    const viewBtn=(canViewAs&&!isUnassigned&&!isActive)?`<button class="btn btn-g btn-sm" style="padding:2px 8px;font-size:10.5px;margin-left:8px" data-branch-id="${escapeHtml(row.branch_id)}" onclick="viewDashboardAsBranch(this.dataset.branchId)" title="View the main dashboard scoped to this branch's own data">View as</button>`:'';
    return `<div style="border:1px solid var(--border);border-radius:10px;padding:9px 11px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
        <span style="font-size:12.5px;font-weight:700;color:var(--text1);display:flex;align-items:center">${escapeHtml(name)}${viewBtn}</span>
        <span class="mono" style="font-size:13px;font-weight:700;color:${profitColor}">${formatAed(profit)}</span>
      </div>
      <div style="display:flex;align-items:center;justify-content:space-between;font-size:10.5px;color:var(--text3)">
        <span>Pending: <span class="mono" style="color:var(--text2)">${pending.count} · ${formatAed(pending.amount)}</span></span>
        <span>Collected: <span class="mono" style="color:var(--text2)">${collected.count} · ${formatAed(collected.amount)}</span></span>
      </div>
    </div>`;
  }).join('');
}

async function viewDashboardAsBranch(branchId){
  if(!branchId)return;
  // switchActiveBranch()'s own syncDashboardFromDatabase() call already
  // re-renders the Branch Performance card (it calls
  // syncBranchPerformanceFromDatabase() on success) — no extra fetch needed
  // here, just the branch switch itself.
  await switchActiveBranch(branchId);
}

async function exitBranchDashboardView(){
  window.ACTIVE_BRANCH_ID=null;
  try{localStorage.removeItem('taxflow_active_branch_id');}catch{}
  _setDashboardTitle(null);
  toast('Showing all branches','ok');
  if(typeof hydrateFromServer==='function'){try{await hydrateFromServer();}catch(e){console.warn('[exitBranchDashboardView] refresh failed',e);}}
  if(typeof syncDashboardFromDatabase==='function'){try{await syncDashboardFromDatabase();}catch(e){console.warn('[exitBranchDashboardView] dashboard refresh failed',e);}}
}

function renderCachedDashboardSnapshot(){
  let cached=null;
  try{cached=JSON.parse(localStorage.getItem('taxflow_dashboard_snapshot')||'null');}catch{}
  if(cached){
    renderDashboardMeta(cached);
    syncSidebarCounts(cached);
    renderFullDashboardFromDatabase(cached);
    return;
  }
  setDashboardStat('Total Revenue + VAT','AED 0.00','Syncing database...');
  setDashboardStat('VAT Payable','AED 0.00','Syncing database...');
  setDashboardStat('Open Invoices','0','Syncing database...');
  setDashboardStat('Staff Present','0/0','Syncing database...');
}

function renderFullDashboardFromDatabase(data){
  const counts=data.module_counts||data;
  const kpis=data.kpis||{
    revenue:data.revenue,
    vat_payable:data.vat_payable,
    open_invoice_count:data.open_invoices,
    open_invoice_amount:0,
    staff_present:data.employee_count,
    staff_total:data.employee_count,
    payroll_net:data.payroll_net
  };
  setDashboardStat('Total Revenue + VAT',formatAed((kpis.revenue||0)+(kpis.output_vat||0)),`${counts.invoice_count||0} invoices in database`);
  setDashboardStat('VAT Payable',formatAed(kpis.vat_payable),`${counts.tax_line_count||0} tax lines - DB period`);
  setDashboardStat('Open Invoices',String(kpis.open_invoice_count||0),`${formatAed(kpis.open_invoice_amount||0)} open amount`);
  setDashboardStat('Staff Present',`${kpis.staff_present||0}/${kpis.staff_total||0}`,`${counts.payroll_run_count||0} payroll run - ${formatAed(kpis.payroll_net||0)} net`);
  renderDashboardHero(data,kpis,counts);
  renderMonthlyRevenueVat(data.monthly_revenue_vat||[]);
  renderRecentActivity(data.recent_activity||[]);
  renderTopCustomers(data.top_customers||[]);
  renderInvoiceStatus(data.invoice_status||{});
  renderStaffToday(data.staff_today||{present:kpis.staff_present||0,total:kpis.staff_total||0,leave:0,absent:0,source:'Employees database'});
  renderCfoRecommendations(data);
  renderDashBankRecon();
}

function _refreshPurchaseDashboardCard(){
  // Called after bootstrap fills _hydratedBills — updates only the purchase card elements
  const lp=_computeLocalPurchaseStats();
  if(!lp.count)return;
  const setEl=(id,v)=>{const el=document.getElementById(id);if(el&&el.textContent==='AED 0.00'||el?.textContent==='0 Bills')el.textContent=v;};
  // Only update if currently showing zero (avoid overwriting good API data)
  const purEl=document.getElementById('dash-total-purchases');
  const purSubEl=document.getElementById('dash-purchases-sub');
  if(purEl&&parseAmount(purEl.textContent||'0')===0&&(lp.total||lp.net)>0){
    purEl.textContent=formatAed(lp.total||lp.net);
    if(purSubEl)purSubEl.textContent=`${lp.count} Bills`;
  }
}

function renderDashboardHero(data,kpis={},counts={}){
  // Header
  const dateEl=document.getElementById('dash-today-date');
  if(dateEl)dateEl.textContent=new Date().toLocaleDateString('en-AE',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
  const periodEl=document.getElementById('dash-period-label');
  if(periodEl)periodEl.textContent=`Live · ${data.period||new Date().toLocaleDateString('en-AE',{month:'long',year:'numeric'})}`;
  applyAppLang(_appLang);

  // Revenue card: collection metrics from invoice_status
  const invStat=data.invoice_status||{};
  const paidInv=invStat.paid||{};
  const pendInv=invStat.pending||{};
  const ovdInv=invStat.overdue||{};
  const totalInv=invStat.total||{};

  // Use invoice_status.total.amount as the authoritative revenue figure
  // (covers both Invoice model rows + AppDataRecord sales); fallback to kpis.revenue
  const revenueNet=parseAmount(totalInv.amount||kpis.total_revenue||kpis.revenue||data.total_revenue||data.revenue||0);
  const outputVatForRevCard=parseAmount(kpis.output_vat||data.output_vat||0);
  const revenue=revenueNet+outputVatForRevCard;
  const invCount=Number(totalInv.count||kpis.invoice_count||counts.invoice_count||0);

  // Purchase card: prefer DB purchase_summary; fall back to live in-memory bill table
  const purSum=data.purchase_summary||{};
  const _localPur=_computeLocalPurchaseStats();
  const purchasesNet=parseAmount(purSum.net||purSum.total||kpis.total_purchases||data.total_purchases||0)||_localPur.net||_localPur.total;
  const inputVatForPurCard=parseAmount(kpis.input_vat||data.input_vat||0);
  const purchases=purchasesNet+inputVatForPurCard;
  const purCount=Number(purSum.total_count||kpis.purchase_count||counts.purchase_record_count||0)||_localPur.count;
  // Fill paid/pending from local data when DB returns zeros
  if(!parseAmount(purSum.paid||0)&&_localPur.paid>0){purSum.paid=_localPur.paid;purSum.paid_count=_localPur.paidCount;purSum.pending_count=_localPur.pendingCount;}

  const vatPayable=parseAmount(kpis.vat_payable||data.vat_payable||0);
  const closingStock=purchaseStockItems().reduce((sum,item)=>sum+Math.max(0,Number(item.available||0))*Number(item.purchase_rate||0),0);
  const directExpenses=[...document.querySelectorAll('#expense-tbody tr:not([data-empty-state])')].reduce((sum,row)=>{
    const cat=(row.children[2]?.textContent||'').trim().toLowerCase();
    return cat.includes('direct')?sum+parseAmount(row.children[5]?.textContent||'0'):sum;
  },0);
  const openingStock=0;
  const grossProfit=revenueNet+closingStock-openingStock-purchasesNet-directExpenses;

  // KPI cards
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
  _revWithVat=formatAed(revenue);
  _revNet=formatAed(revenueNet);
  set('dash-revenue',_revSlideIdx===1?_revNet:_revWithVat);
  set('dash-revenue-sub',`${invCount} invoice${invCount===1?'':'s'}`);
  _purWithVat=formatAed(purchases);
  _purNet=formatAed(purchasesNet);
  set('dash-total-purchases',_purSlideIdx===1?_purNet:_purWithVat);
  set('dash-purchases-sub',`${purCount} bill${purCount===1?'':'s'}`);
  set('dash-vat',formatAed(vatPayable));
  set('dash-vat-sub',vatPayable>0?'Payable to FTA':'Credit position');
  set('dash-gross-profit',formatAed(grossProfit));
  set('dash-total-income',formatAed(revenueNet));
  set('dash-total-expenses',formatAed(purchasesNet));
  set('dash-profit-sub',closingStock>0?`Closing stock: ${formatAed(closingStock)}`:'');
  // Profit card: margin bar
  const marginPct=revenueNet>0?Math.max(0,Math.round(grossProfit/revenueNet*100)):0;
  set('dash-margin-pct',`${marginPct}%`);
  set('dash-margin-pct-big',`${marginPct}%`);
  const marginBar=document.getElementById('dash-profit-margin-bar');
  if(marginBar)marginBar.style.width=Math.min(Math.max(marginPct,0),100)+'%';

  // Trend badges
  const setTrend=(id,val)=>{
    const el=document.getElementById(id);
    if(!el)return;
    if(val>0){el.textContent=`↑ ${val}%`;el.className='dash-kpi-trend up';}
    else if(val<0){el.textContent=`↓ ${Math.abs(val)}%`;el.className='dash-kpi-trend dn';}
    else{el.textContent='—';el.className='dash-kpi-trend';}
  };
  setTrend('dash-rev-trend',Number(kpis.revenue_trend||0));
  setTrend('dash-pur-trend',Number(kpis.purchase_trend||0));
  setTrend('dash-profit-trend',Number(kpis.profit_trend||0));

  // Revenue card detail rows (amount-based collection rate)
  // invoice_status buckets (reports.py) sum Invoice.total (VAT-inclusive)
  // per status, but the "total" bucket itself sums Invoice.subtotal (VAT-
  // exclusive) — dividing the inclusive paidAmt by the exclusive revenueNet
  // inflated the rate by the VAT rate (105% for a fully-collected 5%-VAT
  // book: 105 paid / 100 net). Compare against `revenue` (revenueNet +
  // output VAT — the actual Total Invoice figure) instead, so both sides
  // of the ratio are VAT-inclusive.
  const paidAmt=parseAmount(paidInv.amount||0);
  const colRate=revenue>0?Math.round(paidAmt/revenue*100):0;
  set('dash-rev-collected',formatAed(paidAmt));
  set('dash-rev-paid-count',Number(paidInv.count||0));
  set('dash-rev-rate',colRate+'%');
  set('dash-rev-pending',(Number(pendInv.count||0)+Number(ovdInv.count||0))+' Invoices');
  const revBar=document.getElementById('dash-rev-rate-bar');
  if(revBar)revBar.style.width=Math.min(colRate,100)+'%';


  // Liquid Position card — liqAR uses the same VAT-inclusive `revenue` as
  // colRate above (paidAmt is inclusive). liqAP keeps purchasesNet:
  // purPaidAmt's VAT-inclusiveness isn't consistent here — it can come from
  // _purchase_summary (inclusive) or _computeLocalPurchaseStats()'s bill
  // fallback (net), so switching its denominator isn't a safe like-for-like
  // fix without auditing that function separately.
  const purPaidAmt=parseAmount(purSum.paid||0);
  const liqCash=Math.max(0,paidAmt-purPaidAmt);
  const liqAR=Math.max(0,revenue-paidAmt);
  const liqAP=Math.max(0,purchasesNet-purPaidAmt);
  const liqNet=liqCash+liqAR-liqAP;
  set('dash-liquid-net',formatAed(liqNet));
  set('dash-liquid-cash',formatAed(liqCash));
  set('dash-liquid-ar',formatAed(liqAR));
  set('dash-liquid-ap',formatAed(liqAP));
  const liqBadge=document.getElementById('dash-liquid-badge');
  if(liqBadge){liqBadge.textContent=liqNet>=0?'Positive':'Negative';liqBadge.className='dv2-kpi-badge '+(liqNet>=0?'up':'down');}
  const liqBar=document.getElementById('dash-liquid-bar');
  if(liqBar){const liqTotal=Math.max(1,liqCash+liqAR+liqAP);liqBar.style.width=Math.min(100,Math.max(4,Math.round((liqCash+liqAR)/liqTotal*100)))+'%';}

  // Purchase card detail rows
  const purRate=purchasesNet>0?Math.round(purPaidAmt/purchasesNet*100):0;
  set('dash-pur-paid-amount',formatAed(purPaidAmt));
  set('dash-pur-paid-count',Number(purSum.paid_count||0));
  set('dash-pur-rate',purRate+'%');
  set('dash-pur-pending',Number(purSum.pending_count||0)+' Bills');
  const purBar=document.getElementById('dash-pur-rate-bar');
  if(purBar)purBar.style.width=Math.min(purRate,100)+'%';

  // Sparklines (mini bar charts from monthly data)
  const monthly=data.monthly_revenue_vat||[];
  if(monthly.length){
    renderDashSparkline('dash-rev-spark',monthly.map(r=>Number(r.sales||0)),'#6366f1');
    renderDashSparkline('dash-pur-spark',monthly.map(r=>Number(r.purchases||0)),'#ef4444');
    renderDashSparkline('dash-profit-spark',monthly.map(r=>Number(r.sales||0)-Number(r.purchases||0)),'#10b981');
    renderDashSparkline('dash-vat-spark',monthly.map(r=>Number(r.net_vat||0)),'#f59e0b');
  }

  // AR / AP
  const arPending=parseAmount(kpis.open_invoice_amount||0);
  const arCollected=parseAmount(kpis.collected_amount||0);
  const arGross=arPending+arCollected;
  const arPct=arGross>0?Math.round(arCollected/arGross*100):0;
  set('dash-ar-total',formatAed(arGross));
  set('dash-ar-count',`${Number(kpis.open_invoice_count||0)} invoices`);
  set('dash-ar-pct-collected',`${arPct}%`);
  set('dash-ar-pending',formatAed(arPending));
  set('dash-ar-collected-amt',formatAed(arCollected));
  // AR ring — circumference r=19 ≈ 120
  const arRing=document.getElementById('dash-ar-ring');
  if(arRing)arRing.setAttribute('stroke-dasharray',`${Math.round(arPct/100*120)} 120`);

  const apTotal=parseAmount(kpis.total_payable||purchases);
  const apPaid=parseAmount(kpis.total_paid||0);
  const apDue=Math.max(0,apTotal-apPaid);
  const apPct=apTotal>0?Math.round(apPaid/apTotal*100):0;
  set('dash-ap-total',formatAed(apTotal));
  set('dash-ap-count',`${Number(counts.purchase_record_count||0)} bills`);
  set('dash-ap-pct-paid',`${apPct}%`);
  set('dash-ap-due',formatAed(apDue));
  set('dash-ap-paid-amt',formatAed(apPaid));
  const apRing=document.getElementById('dash-ap-ring');
  if(apRing)apRing.setAttribute('stroke-dasharray',`${Math.round(apPct/100*120)} 120`);

  // VAT ring
  renderDashVatRing(data,kpis);
}

function renderDashSparkline(id,values,color){
  const el=document.getElementById(id);
  if(!el||!values.length)return;
  const max=Math.max(1,...values.map(Math.abs));
  el.innerHTML=values.map(v=>{
    const h=Math.max(3,Math.round((Math.abs(v)/max)*28));
    return `<div class="dash-spark-bar" style="height:${h}px;background:${color};opacity:${v<0?.4:1}"></div>`;
  }).join('');
}

function renderDashVatRing(data,kpis={}){
  const outputVat=parseAmount(kpis.output_vat||data.output_vat||0);
  const inputVat=parseAmount(kpis.input_vat||data.input_vat||0);
  const netVat=outputVat-inputVat;
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
  set('dash-vat-output',formatAed(outputVat));
  set('dash-vat-input',formatAed(inputVat));
  set('dash-vat-net',formatAed(Math.abs(netVat)));
  // Also populate Accounting → Tax Filing VAT widget
  set('acc-filing-output-vat',formatAed(outputVat));
  set('acc-filing-input-vat',formatAed(inputVat));
  set('acc-filing-net-vat',formatAed(Math.abs(netVat)));
  const badge=document.getElementById('dash-vat-status-badge');
  if(badge){badge.textContent=netVat>0?'Payable':netVat<0?'Refund':'Balanced';badge.className=netVat>0?'b b-a':netVat<0?'b b-g':'b b-b';}
  // SVG donut r=38 → circ≈239
  const circ=239;
  const vatTotal=Math.max(1,outputVat+inputVat);
  const outDash=Math.round(outputVat/vatTotal*circ);
  const inDash=Math.round(inputVat/vatTotal*circ);
  const outRing=document.getElementById('dash-vat-ring-output');
  const inRing=document.getElementById('dash-vat-ring-input');
  if(outRing)outRing.setAttribute('stroke-dasharray',`${outDash} ${circ-outDash}`);
  if(inRing){inRing.setAttribute('stroke-dasharray',`${inDash} ${circ-inDash}`);inRing.setAttribute('stroke-dashoffset',`${60+outDash}`);}
  // Gauge arc: fill = output/(output+input) ratio, full arc = 195
  const gaugeArc=document.getElementById('dash-vat-gauge-arc');
  if(gaugeArc){const full=195;const fill=Math.round(outputVat/vatTotal*full);gaugeArc.setAttribute('stroke-dasharray',`${fill} ${full-fill}`);}
}

function renderMonthlyRevenueVat(rows){
  const bars=document.getElementById('dash-monthly-bars');
  const summary=document.getElementById('dash-monthly-summary');
  if(!bars||!summary)return;
  const safeRows=rows.length?rows.slice(-6):[{period:'Current',sales:0,purchases:0,output_vat:0,input_vat:0,net_vat:0}];
  const maxVal=Math.max(1,...safeRows.flatMap(r=>[Number(r.sales||0),Number(r.purchases||0)]));
  bars.style.gridTemplateColumns=`repeat(${safeRows.length},1fr)`;
  bars.innerHTML=safeRows.map(row=>{
    const rH=Math.max(4,Math.round((Number(row.sales||0)/maxVal)*106));
    const pH=Math.max(4,Math.round((Number(row.purchases||0)/maxVal)*106));
    const vH=Math.max(3,Math.round((Math.abs(Number(row.net_vat||0))/maxVal)*106));
    return `<div class="dv2-bar-group">
      <div class="dv2-bar-cols">
        <div class="dv2-bar-col" style="height:${rH}px;background:linear-gradient(to top,#4f46e5,#818cf8)" title="Revenue: ${escapeHtml(formatAed(row.sales))}"></div>
        <div class="dv2-bar-col" style="height:${pH}px;background:linear-gradient(to top,#dc2626,#f87171)" title="Purchases: ${escapeHtml(formatAed(row.purchases))}"></div>
        <div class="dv2-bar-col" style="height:${vH}px;background:linear-gradient(to top,#d97706,#fbbf24)" title="VAT: ${escapeHtml(formatAed(row.net_vat))}"></div>
      </div>
      <div class="dv2-bar-lbl">${escapeHtml(row.period)}</div>
    </div>`;
  }).join('');
  const totalSales=safeRows.reduce((s,r)=>s+Number(r.sales||0),0);
  const totalPurch=safeRows.reduce((s,r)=>s+Number(r.purchases||0),0);
  const totalVat=safeRows.reduce((s,r)=>s+Number(r.net_vat||0),0);
  summary.innerHTML=`
    <div class="dv2-chart-metric"><div class="val" style="color:#6366f1">${escapeHtml(formatAed(totalSales))}</div><div class="lbl">Total Revenue</div></div>
    <div class="dv2-chart-metric"><div class="val" style="color:#ef4444">${escapeHtml(formatAed(totalPurch))}</div><div class="lbl">Total Purchases</div></div>
    <div class="dv2-chart-metric"><div class="val" style="color:#f59e0b">${escapeHtml(formatAed(totalVat))}</div><div class="lbl">Net VAT</div></div>
  `;
}

