// -- ORGANIZATION PAGE -------------------------------------------
function refreshOrgPage(){
  const empRows=[...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')];
  const emps=empRows.map(r=>employeeFromDirectoryRow(r)).filter(e=>e&&e.name&&e.name!=='Employee');
  const total=emps.length;
  const active=emps.filter(e=>(e.status||'Active').toLowerCase()==='active').length;

  // KPIs
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
  set('org-kpi-total',total||'0');
  set('org-kpi-active',active||'0');

  // Dept breakdown — use _deptList as source of truth, enrich with employee counts
  const deptMap={};
  const deptHead={};
  emps.forEach(e=>{
    const d=e.department||'Unassigned';
    deptMap[d]=(deptMap[d]||0)+1;
    if(!deptHead[d]&&(e.designation||'').match(/manager|head|director|vp|chief|ceo|coo|cfo/i))deptHead[d]=e.name;
  });
  // Include all defined departments (even with 0 employees), and set head from _deptList
  if(typeof _deptList!=='undefined'){
    _deptList.filter(d=>d.status!=='Inactive').forEach(d=>{
      if(!(d.name in deptMap))deptMap[d.name]=0;
      if(d.head&&!deptHead[d.name])deptHead[d.name]=d.head;
    });
  }
  const depts=Object.keys(deptMap).sort((a,b)=>deptMap[b]-deptMap[a]);
  set('org-kpi-depts',depts.length||'0');
  const deptCount=document.getElementById('org-dept-count');
  if(deptCount)deptCount.textContent=depts.length+' department'+(depts.length===1?'':'s');
  const deptTbody=document.getElementById('org-dept-tbody');
  if(deptTbody){
    if(!depts.length){
      deptTbody.innerHTML='<tr><td colspan="4" style="text-align:center;color:var(--text3);padding:20px">No employees added yet</td></tr>';
    } else {
      deptTbody.innerHTML=depts.map(d=>{
        const pct=total>0?Math.round(deptMap[d]/total*100):0;
        return `<tr>
          <td><strong>${escapeHtml(d)}</strong></td>
          <td style="text-align:right"><span class="b b-b">${deptMap[d]}</span></td>
          <td style="text-align:right">
            <div style="display:flex;align-items:center;gap:6px;justify-content:flex-end">
              <div style="width:60px;height:6px;border-radius:3px;background:var(--surface2)"><div style="width:${pct}%;height:100%;border-radius:3px;background:var(--accent)"></div></div>
              <span style="font-size:11px;color:var(--text3);min-width:28px">${pct}%</span>
            </div>
          </td>
          <td style="font-size:12px;color:var(--text2)">${escapeHtml(deptHead[d]||'—')}</td>
        </tr>`;
      }).join('');
    }
  }

  // Branch breakdown — use _getBranchNames() as source of truth
  const branchTags=typeof _getBranchNames==='function'?_getBranchNames():[...document.querySelectorAll('#branch-tags-wrap .dept-tag')].map(t=>t.childNodes[0]?.textContent?.trim()).filter(Boolean);
  const branchMap={};
  emps.forEach(e=>{const b=e.branch||e.location||'Dubai HQ';branchMap[b]=(branchMap[b]||0)+1;});
  // Also include defined branches with 0 headcount
  branchTags.forEach(b=>{if(!(b in branchMap))branchMap[b]=0;});
  const branches=Object.keys(branchMap).sort((a,b)=>branchMap[b]-branchMap[a]);
  set('org-kpi-branches',branches.length||'0');
  const branchCount=document.getElementById('org-branch-count');
  if(branchCount)branchCount.textContent=branches.length+' branch'+(branches.length===1?'':'es');
  const branchTbody=document.getElementById('org-branch-tbody');
  if(branchTbody){
    if(!branches.length){
      branchTbody.innerHTML='<tr><td colspan="3" style="text-align:center;color:var(--text3);padding:20px">No branches configured</td></tr>';
    } else {
      branchTbody.innerHTML=branches.map(b=>{
        const cnt=branchMap[b]||0;
        const pct=total>0?Math.round(cnt/total*100):0;
        return `<tr>
          <td><strong>${escapeHtml(b)}</strong></td>
          <td style="text-align:right"><span class="b b-b">${cnt}</span></td>
          <td style="text-align:right">
            <div style="display:flex;align-items:center;gap:6px;justify-content:flex-end">
              <div style="width:60px;height:6px;border-radius:3px;background:var(--surface2)"><div style="width:${pct}%;height:100%;border-radius:3px;background:#f59e0b"></div></div>
              <span style="font-size:11px;color:var(--text3);min-width:28px">${pct}%</span>
            </div>
          </td>
        </tr>`;
      }).join('');
    }
  }

  // Contract/employment type breakdown
  const typeMap={};
  emps.forEach(e=>{const t=e.contract||'Full-Time';typeMap[t]=(typeMap[t]||0)+1;});
  const typeGrid=document.getElementById('org-type-grid');
  if(typeGrid){
    const types=Object.keys(typeMap).sort((a,b)=>typeMap[b]-typeMap[a]);
    if(!types.length){
      typeGrid.innerHTML='<div style="text-align:center;color:var(--text3);padding:20px;grid-column:1/-1">No data</div>';
    } else {
      const colors=['#2563eb','#10b981','#8b5cf6','#f59e0b','#ef4444','#06b6d4','#f97316','#84cc16'];
      typeGrid.innerHTML=types.map((t,i)=>`
        <div style="border:1px solid var(--border);border-radius:8px;padding:12px 14px;text-align:center">
          <div style="font-size:22px;font-weight:700;color:${colors[i%colors.length]}">${typeMap[t]}</div>
          <div style="font-size:11px;color:var(--text2);margin-top:3px">${escapeHtml(t)}</div>
        </div>`).join('');
    }
  }

  // Populate dept filter in org chart
  const deptSel=document.getElementById('org-chart-dept');
  if(deptSel){
    const cur=deptSel.value;
    deptSel.innerHTML='<option value="">All Departments</option>'+depts.map(d=>`<option value="${escapeHtml(d)}"${d===cur?' selected':''}>${escapeHtml(d)}</option>`).join('');
  }

  renderOrgChart();
}

function renderOrgChart(){
  const wrap=document.getElementById('org-chart-wrap');
  if(!wrap)return;
  const filterDept=(document.getElementById('org-chart-dept')?.value||'').toLowerCase();
  const empRows=[...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')];
  let emps=empRows.map(r=>employeeFromDirectoryRow(r)).filter(e=>e&&e.name&&e.name!=='Employee');
  if(filterDept)emps=emps.filter(e=>(e.department||'').toLowerCase()===filterDept);
  if(!emps.length){
    wrap.innerHTML='<div style="text-align:center;color:var(--text3);padding:32px;font-size:13px">No employees to display.</div>';
    return;
  }
  // Build tree: find roots (no supervisor or supervisor not in list)
  const nameSet=new Set(emps.map(e=>e.name));
  const roots=emps.filter(e=>!e.supervisor||!nameSet.has(e.supervisor));
  const childMap={};
  emps.forEach(e=>{
    if(e.supervisor&&nameSet.has(e.supervisor)){
      if(!childMap[e.supervisor])childMap[e.supervisor]=[];
      childMap[e.supervisor].push(e);
    }
  });
  const avatarColors=['#2563eb','#10b981','#8b5cf6','#f59e0b','#ef4444','#06b6d4'];
  const nodeHtml=(emp,depth=0)=>{
    const col=avatarColors[depth%avatarColors.length];
    const ini=initialsFromName(emp.name);
    const children=childMap[emp.name]||[];
    const sub=`<div style="font-size:10px;color:var(--text3)">${escapeHtml(emp.designation||emp.department||'')}</div>`;
    return `<div style="display:flex;flex-direction:column;align-items:center;gap:0;min-width:110px">
      <div style="display:flex;flex-direction:column;align-items:center;cursor:default" title="${escapeHtml(emp.name)} · ${escapeHtml(emp.department||'')}">
        <div style="width:38px;height:38px;border-radius:50%;background:${col};display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:700;flex-shrink:0">${escapeHtml(ini)}</div>
        <div style="margin-top:5px;text-align:center;max-width:100px">
          <div style="font-size:11px;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100px">${escapeHtml(emp.name.split(' ')[0])}</div>
          ${sub}
        </div>
      </div>
      ${children.length?`
        <div style="width:1px;height:16px;background:var(--border)"></div>
        <div style="display:flex;gap:16px;padding-top:0;position:relative">
          <div style="position:absolute;top:0;left:50%;height:1px;width:calc(100% - 40px);background:var(--border);transform:translateX(-50%)"></div>
          ${children.map(c=>`
            <div style="display:flex;flex-direction:column;align-items:center">
              <div style="width:1px;height:16px;background:var(--border)"></div>
              ${nodeHtml(c,depth+1)}
            </div>`).join('')}
        </div>`:''}
    </div>`;
  };
  wrap.innerHTML=`<div style="display:flex;gap:32px;justify-content:center;padding:12px 16px;flex-wrap:wrap">${roots.map(r=>nodeHtml(r,0)).join('<div style="width:1px;background:transparent"></div>')}</div>`;
}

function refreshHrmsKpis(){
  const empCount=document.querySelectorAll('#employee-tbody tr:not([data-empty-state])').length;
  const leaveRows=[...document.querySelectorAll('#leave-tbody tr:not([data-empty-state])')];
  const otRows=[...document.querySelectorAll('#ot-tbody tr:not([data-empty-state])')];
  const corrRows=[...document.querySelectorAll('#corrections-tbody tr:not([data-empty-state])')];
  const today=new Date().toISOString().slice(0,10);
  const onLeaveToday=leaveRows.filter(r=>{
    const cells=[...r.cells];
    const from=cells[2]?.textContent.trim();
    const to=cells[3]?.textContent.trim();
    // renderLeaveTable() writes the real backend's lowercase status strings
    // ('approved'/'pending') into textContent — only the CSS capitalizes
    // them for display. Comparing against Title Case here always failed,
    // pinning onLeaveToday/pendingLeave (and everything derived from them:
    // present/absent counts, the pending-approvals badge) at 0.
    const status=(cells[5]?.textContent.trim()||'').toLowerCase();
    return status==='approved'&&from&&to&&from<=today&&today<=to;
  }).length;
  const pendingLeave=leaveRows.filter(r=>(r.cells[5]?.textContent.trim()||'').toLowerCase()==='pending').length;
  const pendingOT=otRows.filter(r=>r.cells[5]?.textContent.trim()==='Pending').length;
  const pendingCorr=corrRows.filter(r=>r.cells[5]?.textContent.trim()==='Pending').length;
  const payrollRuns=document.querySelectorAll('#payroll-tbody tr:not([data-empty-state])').length;
  const loanRows=document.querySelectorAll('#loans-tbody tr:not([data-empty-state])').length;
  const openRecs=document.querySelectorAll('#requisitions-tbody tr:not([data-empty-state])').length;
  // Count docs expiring within 30 days from expiry-tbody
  const expiryRows=[...document.querySelectorAll('#expiry-tbody tr:not([data-empty-state])')];
  const criticalExpiry=expiryRows.filter(r=>{
    const d=parseInt(r.cells[3]?.textContent)||999;
    return d>=0&&d<=30;
  }).length;
  // Compute net payroll AED total from payroll-tbody .pay-net cells
  let payrollNetTotal=0;
  document.querySelectorAll('#payroll-tbody tr:not([data-empty-state]) .pay-net').forEach(cell=>{
    payrollNetTotal+=parseAmount(cell.textContent);
  });
  const fmtAed=n=>n>=1000?'AED '+(n/1000).toFixed(1)+'K':'AED '+n.toFixed(0);
  const set=(id,val)=>{const el=document.getElementById(id);if(el)el.textContent=val;};
  set('hrms-kpi-emp',empCount||'0');
  set('hrms-kpi-leave',onLeaveToday||'0');
  set('hrms-kpi-pending',(pendingLeave+pendingOT+pendingCorr)||'0');
  set('hrms-kpi-payroll',payrollNetTotal>0?fmtAed(payrollNetTotal):'—');
  // Present Today: show the leave-based estimate immediately, then overwrite
  // with the real punch-based count from /attendance/today once it resolves
  // — this is the same punch data the Attendance Trend chart draws from, so
  // the two can no longer silently disagree (e.g. KPI claiming everyone is
  // present while the trend chart shows near-zero actual check-ins).
  const presentFallback=Math.max(0,empCount-onLeaveToday);
  set('hrms-kpi-present',presentFallback||'0');
  const trendEl=document.getElementById('hrms-kpi-present-trend');
  if(trendEl&&empCount>0)trendEl.innerHTML='<span>'+Math.round(presentFallback/empCount*100)+'% of total</span>';
  moduleApi('/attendance/today').then(data=>{
    const presentToday=data?.present_count;
    if(typeof presentToday!=='number')return;
    set('hrms-kpi-present',presentToday||'0');
    if(trendEl&&empCount>0)trendEl.innerHTML='<span>'+Math.round(presentToday/empCount*100)+'% of total</span>';
  }).catch(()=>{});
  // Dashboard alert tiles
  set('hrms-dash-expiry',criticalExpiry||'0');
  set('hrms-dash-ot',pendingOT||'0');
  set('hrms-dash-recs',openRecs||'0');
  set('hrms-dash-loans',loanRows||'0');
  const badge=(id,val,unit)=>{const el=document.getElementById(id);if(el)el.textContent=val+' '+unit;};
  badge('hrms-badge-emp',empCount||'0','employees');
  badge('hrms-badge-leave',pendingLeave||'0','pending');
  badge('hrms-badge-ot',pendingOT||'0','pending');
  badge('hrms-badge-corr',pendingCorr||'0','pending');
  refreshRecruitmentStats();
  refreshManagerPortalCounts();
}

// Maps the real #emp-leave-policy <option value="..."> strings to annual
// entitlement days. Values must match hrms.html's Leave Policy select exactly.
const _LEAVE_POLICY_DAYS={
  'UAE 30 Calendar':30,
  'UAE Standard':21,
  'Internal 22 Working':22,
  'Internal 29 Working':29,
  'Executive 30 Working':30,
  'Contractor':14,
};
function leaveEntitlementDays(policy){
  return _LEAVE_POLICY_DAYS[policy]??21; // Part-Time/Custom/unknown fall back to the UAE standard baseline
}

function refreshHrmsDashboard(){
  const CIRC=238.76; // 2π × r=38
  const DEPT_COLORS=['#3b82f6','#8b5cf6','#f59e0b','#10b981','#ef4444','#06b6d4','#e879f9','#f97316'];
  const TYPE_COLORS={'Full-Time':'#3b82f6','Part-Time':'#8b5cf6','Contract':'#f59e0b','Daily Wage':'#10b981','Hourly':'#06b6d4','Others':'#d1d5db'};
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};

  // ── Department Strength donut ─────────────────────────────────────
  const empRows=[...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')];
  const deptMap={};
  empRows.forEach(row=>{
    let emp={};try{emp=JSON.parse(row.dataset.employee||'{}');}catch{}
    const dept=(emp.department||row.children[3]?.textContent||'Others').trim()||'Others';
    deptMap[dept]=(deptMap[dept]||0)+1;
  });
  const deptTotal=empRows.length;
  set('hrms-dept-total',deptTotal||'0');
  const deptSvg=document.getElementById('hrms-dept-svg');
  const deptLeg=document.getElementById('hrms-dept-legend');
  if(deptSvg&&deptLeg){
    // Remove existing segments (keep background circle)
    [...deptSvg.querySelectorAll('circle[data-seg]')].forEach(c=>c.remove());
    deptLeg.innerHTML='';
    if(deptTotal>0){
      const sorted=Object.entries(deptMap).sort((a,b)=>b[1]-a[1]);
      let offset=0,ci=0;
      sorted.forEach(([name,cnt])=>{
        const pct=cnt/deptTotal;
        const dash=pct*CIRC;
        const color=DEPT_COLORS[ci%DEPT_COLORS.length];
        const c=document.createElementNS('http://www.w3.org/2000/svg','circle');
        c.setAttribute('cx','50');c.setAttribute('cy','50');c.setAttribute('r','38');
        c.setAttribute('fill','none');c.setAttribute('stroke',color);c.setAttribute('stroke-width','12');
        c.setAttribute('stroke-dasharray',dash.toFixed(1)+' '+(CIRC-dash).toFixed(1));
        c.setAttribute('stroke-dashoffset',(-offset).toFixed(1));
        c.setAttribute('transform','rotate(-90 50 50)');c.setAttribute('data-seg','1');
        deptSvg.appendChild(c);
        deptLeg.innerHTML+=`<div class="hc-legend-row"><div class="hc-dot" style="background:${color}"></div><div class="hc-leg-name">${escapeHtml(name)}</div><div class="hc-leg-pct">(${Math.round(pct*100)}%)</div></div>`;
        offset+=dash;ci++;
      });
    } else {
      deptLeg.innerHTML='<div style="font-size:11px;color:var(--text3)">No employees yet.</div>';
    }
  }

  // ── Employee Type Distribution donut ─────────────────────────────
  const typeMap={};
  empRows.forEach(row=>{
    let emp={};try{emp=JSON.parse(row.dataset.employee||'{}');}catch{}
    const raw=(emp.contract||'Full-Time').trim();
    const key=Object.keys(TYPE_COLORS).find(k=>raw.toLowerCase().includes(k.toLowerCase()))||'Others';
    typeMap[key]=(typeMap[key]||0)+1;
  });
  set('hrms-type-total',deptTotal||'0');
  const typeSvg=document.getElementById('hrms-type-svg');
  const typeLeg=document.getElementById('hrms-type-legend');
  if(typeSvg&&typeLeg){
    [...typeSvg.querySelectorAll('circle[data-seg]')].forEach(c=>c.remove());
    typeLeg.innerHTML='';
    if(deptTotal>0){
      let offset=0;
      Object.entries(typeMap).forEach(([name,cnt])=>{
        const pct=cnt/deptTotal;
        const dash=pct*CIRC;
        const color=TYPE_COLORS[name]||'#d1d5db';
        const c=document.createElementNS('http://www.w3.org/2000/svg','circle');
        c.setAttribute('cx','50');c.setAttribute('cy','50');c.setAttribute('r','38');
        c.setAttribute('fill','none');c.setAttribute('stroke',color);c.setAttribute('stroke-width','12');
        c.setAttribute('stroke-dasharray',dash.toFixed(1)+' '+(CIRC-dash).toFixed(1));
        c.setAttribute('stroke-dashoffset',(-offset).toFixed(1));
        c.setAttribute('transform','rotate(-90 50 50)');c.setAttribute('data-seg','1');
        typeSvg.appendChild(c);
        typeLeg.innerHTML+=`<div class="hc-legend-row"><div class="hc-dot" style="background:${color}"></div><div class="hc-leg-name">${escapeHtml(name)}</div><div class="hc-leg-pct">(${Math.round(pct*100)}%)</div></div>`;
        offset+=dash;
      });
    } else {
      typeLeg.innerHTML='<div style="font-size:11px;color:var(--text3)">No employees yet.</div>';
    }
  }

  // ── Payroll Summary donut + sub-values ───────────────────────────
  let gross=0,allow=0,ot=0,ded=0;
  document.querySelectorAll('#payroll-tbody tr:not([data-empty-state])').forEach(row=>{
    gross+=parseAmount(row.querySelector('.pay-basic')?.value);
    allow+=parseAmount(row.querySelector('.pay-allow')?.value);
    ot+=parseAmount(row.querySelector('.pay-ot')?.value);
    ded+=parseAmount(row.querySelector('.pay-ded')?.value);
  });
  const net=Math.max(0,gross+allow+ot-ded);
  const fmt2=n=>'AED '+n.toLocaleString('en-AE',{minimumFractionDigits:2,maximumFractionDigits:2});
  const fmtK=n=>n>=1000?'AED '+(n/1000).toFixed(1)+'K':'AED '+n.toFixed(0);
  set('hrms-pay-gross',gross>0?fmt2(gross):'—');
  set('hrms-pay-allow',allow>0?fmt2(allow):'—');
  set('hrms-pay-ot-total',ot>0?fmt2(ot):'—');
  set('hrms-pay-ded',ded>0?fmt2(ded):'—');
  set('hrms-pay-net',net>0?fmtK(net):'—');
  set('hrms-payroll-total',net>0?fmtK(net):'—');

  // ── Leave Summary by type ────────────────────────────────────────
  const thisYear=new Date().getFullYear();
  const leaveDays={Annual:0,Sick:0,Casual:0,Emergency:0};
  document.querySelectorAll('#leave-tbody tr:not([data-empty-state])').forEach(row=>{
    const cells=[...row.cells];
    const typeText=(cells[1]?.textContent||'').trim();
    const status=(cells[5]?.textContent||'').trim();
    if(status==='Rejected')return;
    // Check year (from date cell)
    const fromStr=cells[2]?.textContent.trim()||'';
    if(fromStr&&!fromStr.startsWith(thisYear))return;
    const days=parseInt(cells[4]?.textContent)||1;
    if(typeText.includes('Annual'))leaveDays.Annual+=days;
    else if(typeText.includes('Sick'))leaveDays.Sick+=days;
    else if(typeText.includes('Casual'))leaveDays.Casual+=days;
    else if(typeText.includes('Emergency'))leaveDays.Emergency+=days;
  });
  // Entitlement: sum across all employees
  let annualEnt=0,sickEnt=0;
  empRows.forEach(row=>{
    let emp={};try{emp=JSON.parse(row.dataset.employee||'{}');}catch{}
    annualEnt+=leaveEntitlementDays(emp.leave_policy);
    sickEnt+=90;
  });
  const casualEnt=empRows.length*6;   // 6 days per employee (UAE standard)
  const emergEnt=empRows.length*5;    // 5 days per employee
  const setLeave=(valId,fillId,used,total)=>{
    const el=document.getElementById(valId);if(el)el.textContent=total>0?used+' / '+total+' days used':used+' days used';
    const fill=document.getElementById(fillId);if(fill)fill.style.width=(total>0?Math.min(100,Math.round(used/total*100)):0)+'%';
  };
  setLeave('hrms-ls-annual-val','hrms-ls-annual-fill',leaveDays.Annual,annualEnt);
  setLeave('hrms-ls-sick-val','hrms-ls-sick-fill',leaveDays.Sick,sickEnt);
  setLeave('hrms-ls-casual-val','hrms-ls-casual-fill',leaveDays.Casual,casualEnt);
  setLeave('hrms-ls-emerg-val','hrms-ls-emerg-fill',leaveDays.Emergency,emergEnt);

  // ── Recruitment Funnel ──────────────────────────────────────────
  const candRows=[...document.querySelectorAll('#candidates-tbody tr:not([data-empty-state])')];
  const stageOrder=['Applied','Screening','Interview Scheduled','Offer Sent','Hired'];
  const stageCnt={};stageOrder.forEach(s=>stageCnt[s]=0);
  candRows.forEach(row=>{
    const stg=row.dataset.stage||row.cells[6]?.querySelector('.b')?.textContent.trim()||'Applied';
    if(stageCnt.hasOwnProperty(stg))stageCnt[stg]++;
    else stageCnt['Applied']++;
  });
  // Cumulative funnel: each stage includes all beyond it
  const cumApplied=candRows.length;
  const cumScreening=stageCnt['Screening']+(stageCnt['Interview Scheduled']||0)+(stageCnt['Offer Sent']||0)+(stageCnt['Hired']||0);
  const cumInterview=(stageCnt['Interview Scheduled']||0)+(stageCnt['Offer Sent']||0)+(stageCnt['Hired']||0);
  const cumOffer=(stageCnt['Offer Sent']||0)+(stageCnt['Hired']||0);
  const cumHired=stageCnt['Hired']||0;
  const setFunnel=(cntId,barId,val,max)=>{
    set(cntId,val);
    const bar=document.getElementById(barId);
    if(bar)bar.style.width=(max>0?Math.round(val/max*100):0)+'%';
  };
  setFunnel('hrms-funnel-applied','hrms-funnel-bar-applied',cumApplied,cumApplied||1);
  setFunnel('hrms-funnel-screening','hrms-funnel-bar-screening',cumScreening,cumApplied||1);
  setFunnel('hrms-funnel-interview','hrms-funnel-bar-interview',cumInterview,cumApplied||1);
  setFunnel('hrms-funnel-offer','hrms-funnel-bar-offer',cumOffer,cumApplied||1);
  setFunnel('hrms-funnel-hired','hrms-funnel-bar-hired',cumHired,cumApplied||1);

  // ── Assets Overview ─────────────────────────────────────────────
  const assetRows=[...document.querySelectorAll('#assets-tbody tr:not([data-empty-state])')];
  const assetTotal=assetRows.length;
  set('hrms-assets-total',assetTotal||'0');
  const assetsSvg=document.getElementById('hrms-assets-svg');
  const assetsLeg=document.getElementById('hrms-assets-legend');
  if(assetsSvg&&assetsLeg){
    [...assetsSvg.querySelectorAll('circle[data-seg]')].forEach(c=>c.remove());
    if(assetTotal>0){
      const catMap={};
      assetRows.forEach(row=>{
        const cat=(row.cells[1]?.textContent||'Others').trim()||'Others';
        catMap[cat]=(catMap[cat]||0)+1;
      });
      assetsLeg.innerHTML='';
      let offset=0,ci=0;
      Object.entries(catMap).sort((a,b)=>b[1]-a[1]).forEach(([name,cnt])=>{
        const pct=cnt/assetTotal;
        const dash=pct*CIRC;
        const color=DEPT_COLORS[ci%DEPT_COLORS.length];
        const c=document.createElementNS('http://www.w3.org/2000/svg','circle');
        c.setAttribute('cx','50');c.setAttribute('cy','50');c.setAttribute('r','38');
        c.setAttribute('fill','none');c.setAttribute('stroke',color);c.setAttribute('stroke-width','12');
        c.setAttribute('stroke-dasharray',dash.toFixed(1)+' '+(CIRC-dash).toFixed(1));
        c.setAttribute('stroke-dashoffset',(-offset).toFixed(1));
        c.setAttribute('transform','rotate(-90 50 50)');c.setAttribute('data-seg','1');
        assetsSvg.appendChild(c);
        assetsLeg.innerHTML+=`<div class="hc-legend-row"><div class="hc-dot" style="background:${color}"></div><div class="hc-leg-name">${escapeHtml(name)}</div><div class="hc-leg-pct">(${cnt})</div></div>`;
        offset+=dash;ci++;
      });
    } else {
      assetsLeg.innerHTML='<div style="font-size:11px;color:var(--text3)">No assets assigned yet.<br><a style="color:#3b82f6;cursor:pointer" onclick="window.open(\'/hrms\',\'_blank\')">Go to Asset Management →</a></div>';
    }
  }

  // ── Training Overview ────────────────────────────────────────────
  const trainCount=document.querySelectorAll('#training-tbody tr:not([data-empty-state])').length;
  const certCount=document.querySelectorAll('#certs-tbody tr:not([data-empty-state])').length;
  set('hrms-train-programs',trainCount||'0');
  set('hrms-train-certs',certCount||'0');
  const fill1=document.getElementById('hrms-train-programs-fill');
  const fill2=document.getElementById('hrms-train-certs-fill');
  if(fill1)fill1.style.width=(trainCount>0?Math.min(100,trainCount*10):0)+'%';
  if(fill2)fill2.style.width=(certCount>0?Math.min(100,certCount*10):0)+'%';
}

// -- LEAVE MANAGEMENT ------------------------------------------------------
// Backed by the real leave_requests table (backend/app/routers/leave.py),
// not the generic app-data JSON bridge — approvals here actually persist
// and feed the Leave Balance summary from real data, not scraped DOM rows.
let _leaveRequestsCache=[];

async function populateLeaveEmployeeSelect(){
  const sel=document.getElementById('leave-employee');
  if(!sel)return;
  sel.innerHTML='<option value="">Loading employees…</option>';
  try{
    const r=await fetch(`${apiBaseUrl()}/payroll/employees`,{headers:backendHeaders()});
    const employees=r.ok?await r.json():[];
    sel.innerHTML='<option value="">— Select Employee —</option>'+
      employees.map(e=>`<option value="${escapeHtml(e.id)}">${escapeHtml(e.full_name)}</option>`).join('');
  }catch(e){sel.innerHTML='<option value="">Failed to load employees</option>';}
}

async function loadLeaveRequests(){
  const tbody=document.getElementById('leave-tbody');
  if(tbody)tbody.innerHTML='<tr><td colspan="7" class="loading" style="text-align:center;color:var(--text3);padding:20px">Loading…</td></tr>';
  try{
    const r=await fetch(`${apiBaseUrl()}/leave/requests`,{headers:backendHeaders()});
    _leaveRequestsCache=r.ok?await r.json():[];
    renderLeaveTable();
    scheduleIdleTask(updateLeaveBalance,100);
  }catch(e){
    if(tbody)tbody.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--red);padding:20px">Failed to load leave requests.</td></tr>';
  }
}

function renderLeaveTable(){
  const tbody=document.getElementById('leave-tbody');
  if(!tbody)return;
  if(!_leaveRequestsCache.length){
    tbody.innerHTML='<tr data-empty-state><td colspan="7" style="text-align:center;color:var(--text3);padding:20px">No leave requests yet.</td></tr>';
    return;
  }
  tbody.innerHTML=_leaveRequestsCache.map(rec=>{
    const statusCls=rec.status==='approved'?'b-g':rec.status==='rejected'?'b-r':'b-a';
    const typeCls={Annual:'b-a',Sick:'b-t',Emergency:'b-p',Unpaid:'b-gray',Hajj:'b-b'}[rec.leave_type?.replace(' Leave','')]||'b-b';
    const actions=rec.status==='pending'
      ?`<div class="flx"><button class="btn btn-success btn-sm" onclick="approveLeave('${escapeHtml(rec.id)}')">✓</button><button class="btn btn-danger btn-sm" onclick="rejectLeave('${escapeHtml(rec.id)}')">✕</button></div>`
      :`<span class="b ${statusCls}" style="text-transform:capitalize">${escapeHtml(rec.status)}</span>`;
    return `<tr data-record-id="${escapeHtml(rec.id)}">
      <td>${escapeHtml(rec.employee_name)}</td>
      <td><span class="b ${typeCls}">${escapeHtml(rec.leave_type?.replace(' Leave','')||rec.leave_type)}</span></td>
      <td>${escapeHtml(rec.start_date)}</td>
      <td>${escapeHtml(rec.end_date)}</td>
      <td>${rec.days||'—'}</td>
      <td><span class="b ${statusCls}" style="text-transform:capitalize">${escapeHtml(rec.status)}</span></td>
      <td>${actions}</td>
    </tr>`;
  }).join('');
}

async function approveLeave(id){
  try{
    const r=await fetch(`${apiBaseUrl()}/leave/requests/${id}/approve`,{method:'POST',headers:backendHeaders()});
    if(r.ok){
      toast('Leave approved ✓','ok');
      audit('Leave approved',id,'Approved');
      loadLeaveRequests();
    }else{const d=await r.json().catch(()=>({}));toast(d.detail||'Failed to approve','err');}
  }catch(e){toast('Cannot reach server','err');}
}

async function rejectLeave(id){
  try{
    const r=await fetch(`${apiBaseUrl()}/leave/requests/${id}/reject`,{method:'POST',headers:backendHeaders()});
    if(r.ok){
      toast('Leave rejected','warn');
      audit('Leave rejected',id,'Rejected');
      loadLeaveRequests();
    }else{const d=await r.json().catch(()=>({}));toast(d.detail||'Failed to reject','err');}
  }catch(e){toast('Cannot reach server','err');}
}

async function saveLeaveRequest(){
  const employeeId=document.getElementById('leave-employee')?.value||'';
  const leaveType=document.getElementById('leave-type')?.value.trim()||'';
  const from=document.getElementById('leave-from')?.value||'';
  const to=document.getElementById('leave-to')?.value||'';
  const reason=document.getElementById('leave-reason')?.value.trim()||'';
  if(!employeeId||!from||!to){toast('Employee, From and To dates are required','warn');return;}
  if(to<from){toast('To date cannot be before From date','warn');return;}
  try{
    const r=await fetch(`${apiBaseUrl()}/leave/requests`,{method:'POST',headers:backendHeaders(),body:JSON.stringify({
      employee_id:employeeId,leave_type:leaveType,start_date:from,end_date:to,reason:reason||null,
    })});
    if(r.ok){
      closeM('m-leave');
      document.getElementById('leave-reason').value='';
      toast('Leave request submitted ✓','ok');
      audit('Leave request submitted',employeeId,'Pending');
      loadLeaveRequests();
    }else{
      const d=await r.json().catch(()=>({}));
      toast(d.detail||'Failed to submit leave request','err');
    }
  }catch(e){toast('Cannot reach server','err');}
}

// ── Leave Calendar ────────────────────────────────────────────────────────────
let _leaveCalYear=new Date().getFullYear();
let _leaveCalMonth=new Date().getMonth(); // 0-based

function leaveCalNav(dir){
  _leaveCalMonth+=dir;
  if(_leaveCalMonth>11){_leaveCalMonth=0;_leaveCalYear++;}
  if(_leaveCalMonth<0){_leaveCalMonth=11;_leaveCalYear--;}
  renderLeaveCalendar();
}

function renderLeaveCalendar(){
  const cal=document.getElementById('leave-calendar');
  const label=document.getElementById('leave-cal-label');
  if(!cal)return;
  const year=_leaveCalYear, month=_leaveCalMonth;
  const monthName=new Date(year,month,1).toLocaleString('en-AE',{month:'long',year:'numeric'});
  if(label)label.textContent=monthName;
  const daysInMonth=new Date(year,month+1,0).getDate();
  const firstDow=new Date(year,month,1).getDay(); // 0=Sun

  // Collect leave records for this month
  const leaveRows=[...document.querySelectorAll('#leave-tbody tr')];
  const typeColour={Annual:'rgba(108,92,231,.25)',Sick:'rgba(0,206,201,.25)',Emergency:'rgba(253,203,110,.35)',Unpaid:'rgba(150,150,150,.2)',Hajj:'rgba(99,205,218,.25)'};
  // Build per-employee leave map: empName -> Set of date strings 'YYYY-MM-DD'
  const empLeave={}; // empName -> {date:'TYPE'}
  leaveRows.forEach(row=>{
    const cells=[...row.cells];
    if(cells.length<4)return;
    const emp=cells[0]?.textContent.trim();
    const type=cells[1]?.textContent.trim();
    const from=cells[2]?.textContent.trim();
    const to=cells[3]?.textContent.trim();
    const status=(cells[5]?.textContent.trim()||'').toLowerCase();
    if(status==='rejected')return;
    if(!emp||!from||!to)return;
    if(!empLeave[emp])empLeave[emp]={};
    const d=new Date(from);
    const end=new Date(to);
    while(d<=end){
      const key=d.toISOString().split('T')[0];
      if(d.getFullYear()===year&&d.getMonth()===month)empLeave[emp][key]=type;
      d.setDate(d.getDate()+1);
    }
  });
  const employees=Object.keys(empLeave);
  if(!employees.length){
    cal.innerHTML='<div style="padding:24px;text-align:center;color:var(--muted)">No leave records for this month.</div>';
    return;
  }

  // Day headers
  const days=Array.from({length:daysInMonth},(_,i)=>i+1);
  const today=new Date();
  let html='<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:11px"><thead><tr>';
  html+='<th style="padding:6px 8px;background:var(--surface2);min-width:120px;text-align:left;border-bottom:1px solid var(--border)">Employee</th>';
  days.forEach(d=>{
    const isToday=year===today.getFullYear()&&month===today.getMonth()&&d===today.getDate();
    const dow=new Date(year,month,d).toLocaleString('en-AE',{weekday:'short'}).slice(0,2);
    const isWeekend=[0,6].includes(new Date(year,month,d).getDay());
    html+=`<th style="padding:4px 2px;text-align:center;min-width:28px;background:${isToday?'rgba(108,92,231,.15)':isWeekend?'var(--hover)':'var(--surface2)'};border-bottom:1px solid var(--border);color:${isWeekend?'var(--muted)':'var(--text)'}"><div>${d}</div><div style="font-size:9px;color:var(--muted)">${dow}</div></th>`;
  });
  html+='</tr></thead><tbody>';
  employees.forEach(emp=>{
    html+=`<tr><td style="padding:6px 8px;font-weight:500;border-bottom:1px solid var(--border);white-space:nowrap">${escapeHtml(emp)}</td>`;
    days.forEach(d=>{
      const key=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const type=empLeave[emp][key];
      const isWeekend=[0,6].includes(new Date(year,month,d).getDay());
      const bg=type?(typeColour[type.replace(' Leave','')]||'rgba(108,92,231,.2)'):(isWeekend?'var(--hover)':'');
      html+=`<td style="padding:2px;text-align:center;border-bottom:1px solid var(--border);background:${bg}" title="${type||''}">${type?'●':''}</td>`;
    });
    html+='</tr>';
  });
  // Legend
  html+='</tbody></table></div><div style="display:flex;gap:12px;padding:10px 8px;font-size:11px;flex-wrap:wrap">';
  Object.entries(typeColour).forEach(([t,c])=>{
    html+=`<span style="display:flex;align-items:center;gap:4px"><span style="width:12px;height:12px;border-radius:2px;background:${c};display:inline-block"></span>${t}</span>`;
  });
  html+='</div>';
  cal.innerHTML=html;
}
// ─────────────────────────────────────────────────────────────────────────────

function updateLeaveBalance(){
  const tbody=document.getElementById('leave-balance-tbody');
  if(!tbody)return;
  const empRows=[...document.querySelectorAll('#employee-tbody tr:not([data-empty-state])')];
  if(!empRows.length){emptyTableMessage(tbody,'No employees in database yet.');return;}
  const leaveRows=[...document.querySelectorAll('#leave-tbody tr:not([data-empty-state])')];
  // Bucketed by (employee, leave type, approved-vs-pending) — previously
  // every non-rejected leave row, regardless of type, was summed into one
  // "used" number and subtracted from Annual Leave's remaining balance, so
  // taking Sick/Emergency/Unpaid leave silently drained the Annual figure
  // while the separate "Sick Days" column stayed hardcoded at 90 forever.
  // Pending requests are still held back against Remaining (a real backend
  // over-entitlement check now blocks approving past what's left, so a
  // pending hold here prevents someone stacking several unapproved
  // overlapping requests that would each individually look fine) — but
  // they're now shown in their own column instead of silently merged into
  // "Used", which used to make it look like unapproved leave had already
  // been taken.
  const usedByType={},pendingByType={};
  leaveRows.forEach(row=>{
    const cells=[...row.cells];
    if(cells.length<6)return;
    const emp=cells[0]?.textContent.trim();
    const type=cells[1]?.textContent.trim()||'Annual';
    const days=parseInt(cells[4]?.textContent||'0')||0;
    const status=(cells[5]?.textContent.trim()||'').toLowerCase();
    if(!emp)return;
    if(status==='approved'){
      usedByType[emp]=usedByType[emp]||{};
      usedByType[emp][type]=(usedByType[emp][type]||0)+days;
    }else if(status==='pending'){
      pendingByType[emp]=pendingByType[emp]||{};
      pendingByType[emp][type]=(pendingByType[emp][type]||0)+days;
    }
  });
  tbody.innerHTML='';
  empRows.forEach(row=>{
    const emp=employeeFromDirectoryRow(row);
    if(!emp.name)return;
    const policy=emp.leave_policy||'UAE Standard';
    const annualDays=leaveEntitlementDays(policy);
    const sickDays=90;
    const empUsed=usedByType[emp.name]||{};
    const empPending=pendingByType[emp.name]||{};
    const used=empUsed['Annual']||0;
    const pending=empPending['Annual']||0;
    const sickUsed=empUsed['Sick']||0;
    const remaining=Math.max(0,annualDays-used-pending);
    const sickRemaining=Math.max(0,sickDays-sickUsed);
    const tr=document.createElement('tr');
    tr.innerHTML=`<td>${escapeHtml(emp.name)}</td><td class="mono">${annualDays}</td><td class="mono">${sickRemaining}</td><td class="mono">${used}</td><td class="mono">${pending}</td><td class="mono" ${remaining<5?'style="color:var(--red)"':''}>${remaining}</td>`;
    tbody.appendChild(tr);
  });
  if(!tbody.children.length)emptyTableMessage(tbody,'No employees in database yet.');
}

function updateOtMultiplier(){
  const type=document.getElementById('ot-type')?.value||'normal';
  const multEl=document.getElementById('ot-multiplier');
  const noteEl=document.getElementById('ot-mult-note');
  if(!multEl)return;
  // Read the actual configured rates from HR Settings > OT Rules (saved via
  // saveOtRules(), reloaded into these fields by _applyOtRulesConfig()) —
  // previously hardcoded 1.25/1.5 regardless of what an admin had configured.
  const normalRate=parseFloat(document.getElementById('ot-mult-normal')?.value)||1.25;
  const weekendRate=parseFloat(document.getElementById('ot-mult-weekend')?.value)||1.5;
  const holidayRate=parseFloat(document.getElementById('ot-mult-holiday')?.value)||weekendRate;
  const ramadanRate=parseFloat(document.getElementById('ot-mult-ramadan')?.value)||normalRate;
  let mult=`${normalRate}×`,note='UAE Labour Law';
  if(type==='weekend'){mult=`${weekendRate}×`;note='Weekend rate';}
  else if(type==='holiday'){mult=`${holidayRate}×`;note='Holiday rate';}
  else if(type==='ramadan'){mult=`${ramadanRate}×`;note='Ramadan OT rate';}
  multEl.value=mult;
  if(noteEl)noteEl.textContent=note;
  const start=document.getElementById('ot-login')?.value||'';
  const end=document.getElementById('ot-logout')?.value||'';
  const hoursEl=document.getElementById('ot-hours');
  if(hoursEl&&start&&end&&!hoursEl.value){
    const [sh,sm]=start.split(':').map(Number);
    const [eh,em]=end.split(':').map(Number);
    let mins=(eh*60+em)-(sh*60+sm);
    if(mins<0)mins+=24*60;
    hoursEl.value=(mins/60).toFixed(2);
  }
}

function previewEmpPhoto(input){
  const preview=document.getElementById('emp-photo-preview');
  if(!preview||!input.files||!input.files[0])return;
  const reader=new FileReader();
  reader.onload=e=>{preview.innerHTML=`<img src="${e.target.result}" style="width:100%;height:100%;object-fit:cover">`};
  reader.readAsDataURL(input.files[0]);
}

// Compressed (not the raw upload) — this ends up embedded in every saved
// products AppDataRecord and gets fetched on every POS page load across
// however many products exist, so keeping it small matters a lot more
// here than for a single employee's own profile photo.
async function previewInvItemPhoto(input){
  const preview=document.getElementById('inv-item-photo-preview');
  if(!preview||!input.files||!input.files[0])return;
  const reader=new FileReader();
  reader.onload=async e=>{
    const compressed=await compressImageBase64(e.target.result,400,400,0.75);
    preview.dataset.image=compressed;
    preview.innerHTML=`<img src="${compressed}" style="width:100%;height:100%;object-fit:cover">`;
  };
  reader.readAsDataURL(input.files[0]);
}

