// ── Biometric Device Management ───────────────────────────────────────────────

async function loadBiometricDevices(){
  const tbody=document.getElementById('bio-devices-tbody');
  if(!tbody)return;
  try{
    const res=await moduleApi('/attendance/devices');
    const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
    if(!res||!Array.isArray(res)){tbody.innerHTML='<tr data-empty-state><td colspan="8" style="text-align:center;color:var(--text3);padding:32px">No devices configured.</td></tr>';return;}
    // KPIs
    set('bio-kpi-total',res.length);
    set('bio-kpi-active',res.filter(d=>d.status==='active').length);
    if(!res.length){tbody.innerHTML='<tr data-empty-state><td colspan="8" style="text-align:center;color:var(--text3);padding:32px">No biometric devices configured. Click <strong>+ Add Device</strong> to connect your first device.</td></tr>';return;}
    tbody.innerHTML='';
    let latestSync=null;
    res.forEach(d=>{
      if(d.last_sync&&(!latestSync||d.last_sync>latestSync))latestSync=d.last_sync;
      const tr=document.createElement('tr');
      tr.dataset.deviceId=d.id;
      const statusCls=d.status==='active'?'b-g':'b-r';
      const lastSync=d.last_sync?new Date(d.last_sync).toLocaleString('en-AE'):'Never';
      const isBioTime=BIO_BIOTIME_TYPES.has(d.device_type);
      const isAdmsClassic=BIO_ADMS_CLASSIC_TYPES.has(d.device_type);
      const addrCol=isBioTime
        ?`<td class="mono" colspan="2" style="font-size:11px">${escapeHtml((d.biotime_base_url||'—').replace(/^https?:\/\//,''))}</td>`
        :isAdmsClassic
        ?`<td class="mono" colspan="2" style="font-size:11px">SN: ${escapeHtml(d.serial_number||'—')}</td>`
        :`<td class="mono">${escapeHtml(d.ip_address||'—')}</td><td class="mono">${d.port||'—'}</td>`;
      const actionsCol=isBioTime
        ?`<button class="btn btn-p btn-sm" onclick="syncBiometricDeviceNow('${escapeHtml(d.id)}',this)">Sync Now</button><button class="btn btn-g btn-sm" onclick="testBiometricDevice('${escapeHtml(d.id)}',this)">Test</button>`
        :`<button class="btn btn-p btn-sm" onclick="showBioGuide(null,'${escapeHtml(d.device_type)}','${escapeHtml(d.ip_address||'')}',${d.port||4370},'${escapeHtml(d.serial_number||'')}')">Guide</button><button class="btn btn-g btn-sm" onclick="testBiometricDevice('${escapeHtml(d.id)}',this)">Test</button>`;
      tr.innerHTML=`<td>${escapeHtml(d.name)}</td><td><span class="b b-b" style="font-size:10px">${escapeHtml(d.device_type)}</span></td>${addrCol}<td>${escapeHtml(d.location||'—')}</td><td><span class="b ${statusCls}">${escapeHtml(d.status)}</span></td><td class="mono" style="font-size:11px">${lastSync}</td><td><div class="flx">${actionsCol}<button class="btn btn-danger btn-sm" onclick="deleteBiometricDevice('${escapeHtml(d.id)}',this)">Remove</button></div></td>`;
      tbody.appendChild(tr);
    });
    if(latestSync)set('bio-kpi-last',new Date(latestSync).toLocaleTimeString('en-AE'));
  }catch(e){toast('Failed to load devices: '+e,'warn');}
}

async function loadBioSyncLog(){
  const log=document.getElementById('bio-sync-log');
  if(!log)return;
  log.innerHTML='<div style="color:var(--text3);padding:16px;text-align:center">Loading…</div>';
  try{
    const res=await moduleApi('/attendance/punches?limit=50');
    const punches=res.punches||[];
    const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
    set('bio-kpi-punches',punches.length);
    if(!punches.length){
      log.innerHTML='<div style="color:var(--text3);padding:32px;text-align:center">No punch records yet — connect a device or import CSV.</div>';
      return;
    }
    if(punches[0])set('bio-kpi-last',new Date(punches[0].punch_time).toLocaleTimeString('en-AE'));
    log.innerHTML='';
    punches.forEach(p=>{
      const dt=new Date(p.punch_time);
      const timeStr=dt.toLocaleString('en-AE',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'});
      const dirClr=p.direction==='out'?'var(--amber)':'var(--green)';
      const dirIcon=p.direction==='out'?'↖':'→';
      const srcBadge=p.source==='csv'?'<span style="color:var(--purple)">CSV</span>':p.source==='device'?'<span style="color:var(--blue)">BIO</span>':'<span style="color:var(--text3)">MAN</span>';
      const name=escapeHtml(p.employee_name||p.employee_id);
      const dev=p.device_name?` · ${escapeHtml(p.device_name)}`:'';
      // No employee has this ID (Staff → Employees) — the punch was stored
      // but will never attach to anyone anywhere else in the app (Present
      // Today, payslips, attendance reports). Flag it here since this log
      // is the one place an admin could actually notice.
      const unmatchedBadge=p.matched===false?' <span style="color:var(--red)" title="No employee has this ID — check Staff → Employees">⚠ Unmatched</span>':'';
      const row=document.createElement('div');
      row.style.cssText='padding:3px 6px;border-bottom:1px solid var(--divider)';
      row.innerHTML=`<span style="color:${dirClr}">${dirIcon} ${timeStr}</span>  ${srcBadge}  <strong>${name}</strong>${dev}  <span style="color:var(--text3)">${escapeHtml(p.direction)}</span>${unmatchedBadge}`;
      log.appendChild(row);
    });
  }catch(e){
    log.innerHTML='<div style="color:var(--text3);padding:32px;text-align:center">Unable to load sync log.</div>';
  }
}

const BIO_TCP_TYPES=new Set(['ZKTeco F Series','ZKTeco K Series','ZKTeco iClock','ZKTeco X Face Pro','ZKTeco SpeedFace','ZKTeco ProFace','ZKTeco G Series','ZKTeco UA Series','ZKTeco IN Series','ZKTeco MB Series','ZKTeco','Anviz']);
const BIO_PUSH_TYPES=new Set(['ZKTeco ADMS','Suprema','Hikvision']);
const BIO_BIOTIME_TYPES=new Set(['ZKTeco BioTime Server']);
// Real ZKTeco ADMS Cloud Server Mode — a device whose own menu has only a
// fixed Server IP + Port field (no custom URL/header, unlike BIO_PUSH_TYPES
// above), identified by hardware serial number instead of a device key.
const BIO_ADMS_CLASSIC_TYPES=new Set(['ZKTeco ADMS Classic']);

function onBioDevTypeChange(val){
  const hint=document.getElementById('bio-dev-mode-hint');
  const netRow=document.getElementById('bio-dev-net-row');
  const biotimeRow=document.getElementById('bio-dev-biotime-row');
  const serialRow=document.getElementById('bio-dev-serial-row');
  const portEl=document.getElementById('bio-dev-port');
  const saveBtn=document.getElementById('bio-dev-save-btn');
  if(!hint)return;
  if(biotimeRow)biotimeRow.style.display=BIO_BIOTIME_TYPES.has(val)?'':'none';
  if(serialRow)serialRow.style.display=BIO_ADMS_CLASSIC_TYPES.has(val)?'':'none';
  if(saveBtn)saveBtn.textContent=BIO_BIOTIME_TYPES.has(val)?'Connect BioTime Server':(BIO_ADMS_CLASSIC_TYPES.has(val)?'Add Device':'Add Device & Get Device Key');
  if(val==='Manual'){
    hint.style.cssText='margin:8px 0 12px;padding:9px 13px;border-radius:8px;font-size:12px;line-height:1.6;background:var(--bg2);color:var(--text3)';
    hint.innerHTML='<strong>Mode: Manual / CSV</strong> — No device connection needed. Use the <em>Import CSV</em> button to upload attendance records.';
    if(netRow)netRow.style.display='none';
  } else if(val==='ZKTeco ADMS'){
    hint.style.cssText='margin:8px 0 12px;padding:9px 13px;border-radius:8px;font-size:12px;line-height:1.6;background:var(--amber-bg);color:var(--amber)';
    hint.innerHTML='<strong>Mode: ADMS Cloud Push</strong> — On the device panel, set: <em>ADMS Server → this server\'s URL</em>. The device pushes punches automatically. No bridge script needed.';
    if(netRow)netRow.style.display='none';
  } else if(BIO_ADMS_CLASSIC_TYPES.has(val)){
    hint.style.cssText='margin:8px 0 12px;padding:9px 13px;border-radius:8px;font-size:12px;line-height:1.6;background:var(--amber-bg);color:var(--amber)';
    hint.innerHTML='<strong>Mode: ADMS Classic (Cloud Server)</strong> — For devices whose own menu only has a Server IP + Port field, nothing configurable. No key needed — the device identifies itself by its own serial number, entered below. No bridge script needed.';
    if(netRow)netRow.style.display='none';
  } else if(BIO_BIOTIME_TYPES.has(val)){
    hint.style.cssText='margin:8px 0 12px;padding:9px 13px;border-radius:8px;font-size:12px;line-height:1.6;background:var(--blue-bg);color:var(--blue)';
    hint.innerHTML='<strong>Mode: BioTime Pull</strong> — TaxFlow connects directly to your existing BioTime server every 5 minutes and pulls attendance for all its terminals. No bridge software needed. Requires each employee\'s <em>Employee No.</em> to match their BioTime personnel ID.';
    if(netRow)netRow.style.display='none';
  } else if(BIO_PUSH_TYPES.has(val)){
    hint.style.cssText='margin:8px 0 12px;padding:9px 13px;border-radius:8px;font-size:12px;line-height:1.6;background:var(--amber-bg);color:var(--amber)';
    hint.innerHTML='<strong>Mode: HTTP Webhook Push</strong> — Configure the device to POST punches to <code>/api/v1/punch</code> with header <code>X-Device-Key: &lt;key&gt;</code>.';
    if(netRow)netRow.style.display='none';
  } else {
    hint.style.cssText='margin:8px 0 12px;padding:9px 13px;border-radius:8px;font-size:12px;line-height:1.6;background:var(--blue-bg);color:var(--blue)';
    const isAnviz=val==='Anviz';
    const defPort=isAnviz?'5010':'4370';
    hint.innerHTML=`<strong>Mode: TCP/IP Pull</strong> — Run <code>zk_bridge.py</code> on the same LAN as this device. It polls every 30 s and forwards punches to the API. Default port ${defPort}.`;
    if(netRow)netRow.style.display='';
    if(portEl&&(portEl.value==='4370'||portEl.value==='5010'))portEl.value=defPort;
  }
}

async function downloadBridgeScript(){
  try{
    const token=localStorage.getItem('taxflow_token')||'';
    const base=(window.TAXFLOW_API_BASE_URL||'').replace(/\/$/,'')||'http://localhost:8000';
    const resp=await fetch(`${base}/api/v1/attendance/bridge-script`,{
      headers:{Authorization:`Bearer ${token}`}
    });
    if(!resp.ok){toast('Download failed: '+resp.status,'warn');return;}
    const text=await resp.text();
    const blob=new Blob([text],{type:'text/plain'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;a.download='zk_bridge.py';a.click();
    setTimeout(()=>URL.revokeObjectURL(url),2000);
  }catch(e){toast('Download error: '+e,'warn');}
}

function downloadBioConfig(content){
  const blob=new Blob([content],{type:'text/plain'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='zk_bridge.conf';a.click();
  setTimeout(()=>URL.revokeObjectURL(url),2000);
}

