function applyAppLang(lang){
  _appLang=lang||'en';
  localStorage.setItem(_LANG_KEY,_appLang);
  const isAr=_appLang==='ar';
  document.documentElement.setAttribute('dir',isAr?'rtl':'ltr');
  document.documentElement.setAttribute('lang',isAr?'ar':'en');
  const enBtn=document.getElementById('dash-lang-en');
  const arBtn=document.getElementById('dash-lang-ar');
  if(enBtn)enBtn.classList.toggle('active',!isAr);
  if(arBtn)arBtn.classList.toggle('active',isAr);
  const t=_LANG[_appLang]||_LANG.en;
  const h=new Date().getHours();
  const greetKey=h<12?'greeting_am':h<17?'greeting_pm':'greeting_eve';
  const greet=document.getElementById('dash-greeting');
  if(greet)greet.textContent=t[greetKey];
  const sub=document.getElementById('dash-subtitle');
  if(sub)sub.textContent=t.subtitle;
  const niLabel=document.getElementById('dash-btn-new-invoice-label');
  if(niLabel)niLabel.textContent=t.new_invoice;
  const apLabel=document.getElementById('dash-btn-add-purchase-label');
  if(apLabel)apLabel.textContent=t.add_purchase;
  // Translate all data-i18n elements
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key=el.dataset.i18n;
    if(t[key]!==undefined)el.textContent=t[key];
  });
  // Refresh active page title / subtitle
  const activePage=(document.querySelector('.page.on')?.id||'').replace(/^page-/,'')||'dashboard';
  const activeMeta=META[activePage];
  if(activeMeta){
    const arMeta=isAr?(_META_AR[activePage]||{}):null;
    const ptitle=document.getElementById('ptitle');
    const psubtitle=document.getElementById('psub');
    if(ptitle)ptitle.textContent=arMeta?.t||activeMeta.t;
    if(psubtitle)psubtitle.textContent=arMeta?.s||activeMeta.s;
  }
}

function setAppLang(lang){applyAppLang(lang);}

function initApp(){
  if(window.__taxflowAppInitialized)return;
  window.__taxflowAppInitialized=true;
  const _SNAP_VER='20260613t';
  if(localStorage.getItem('taxflow_snap_ver')!==_SNAP_VER){
    localStorage.removeItem('taxflow_dashboard_snapshot');
    localStorage.setItem('taxflow_snap_ver',_SNAP_VER);
  }
  if(localStorage.getItem('sb-hidden')==='1'&&window.innerWidth>1100){
    document.body.classList.add('sb-hidden');
  }
  _applyLogoEverywhere();
  applyTheme('light');
  const today=new Date().toISOString().split('T')[0];
  document.querySelectorAll('input[type=date]').forEach(i=>{if(!i.value)i.value=today;});
  const invDate=document.getElementById('inv-date');
  if(invDate)invDate.value=today;
  const due=new Date();
  due.setDate(due.getDate()+30);
  const invDue=document.getElementById('inv-due');
  if(invDue)invDue.value=due.toISOString().split('T')[0];

  document.addEventListener('keydown',event=>{
    if(event.key==='Escape'){
      closeSidebar();
      document.querySelectorAll('.overlay.on').forEach(modal=>modal.classList.remove('on'));
    }
  });
  applyAppLang(_appLang);
  mergeBankAndPaymentsModule();
  separateCorporateAccountingModule();
  clearStaticDemoData();
  renderAttendanceCalendar();
  watchVisibleTablePagination();
  applyAllTableActions();
  updateBackButton();

  restoreSalesInvoices();
  restoreAIThread();
  // /ai/workbench is a User-only endpoint (get_current_user) — for an HRMS
  // sub-user (Employee principal) or a Branch Login Phase 2 session (Branch
  // principal) it 401s, which authenticatedFetch treats as an invalid
  // session and force-logs them out. Same guard as syncCompanyFromDatabase()
  // etc. below.
  if(document.getElementById('page-ai')&&!['employee','branch'].includes(localStorage.getItem('taxflow_principal_kind'))){
    scheduleIdleTask(loadAIWorkbench,600);
  }
  renderAuditLog();
  initInvoiceLayouts();
  updateInvoiceLayoutPreview();
  setQuotationLayoutFields();
  updateQuotationLayoutPreview();
  syncProductMasterOptions();
  setManualPurchaseDefaults();
  configureSalesFormMode();
  configureManualPurchaseMode();
  // syncCompanyFromDatabase/loadUsersIntoTable call User-only endpoints
  // (/companies/current — actually widened to any Principal since Branch
  // Management Phase 6, but left gated here for company-display purposes
  // since applyHrmsPermissionNav()/applyMainDashboardPermissionNav()
  // already cover that via /auth/whoami; /app-data/users is genuinely
  // User-only) — for an HRMS sub-user (Employee principal) or a Branch
  // Login Phase 2 session (Branch principal) a true User-only 401 (no User
  // row matches an "emp:"/"branch:" subject) is treated as an invalid
  // session and force-logs them out before the page even renders.
  //
  // syncDashboardFromDatabase() used to be lumped in with these two, but
  // /reports/dashboard (and /reports/branch-performance, which it also
  // calls) use require_principal_permission("reports:view") — Principal-
  // aware, not User-only — so it never actually risked that 401. Gating it
  // here instead left every Dashboard stat tile at its static "AED 0.00"
  // placeholder forever for a Branch/Employee session with Reports access
  // (Main Dashboard Branch Access), since nothing else ever populated them.
  if(!['employee','branch'].includes(localStorage.getItem('taxflow_principal_kind'))){
    syncCompanyFromDatabase();
    renderBusinessLocationRows();
    loadUsersIntoTable();
  }
  enhancePageTables('page-dashboard');
  syncDashboardFromDatabase().catch(err=>console.warn('Dashboard sync failed during init:',err));
  hydrateFromServer().catch(err=>console.warn('Database hydrate failed during init:',err));
  const _lastPage=window.HRMS_STANDALONE?'hrms':localStorage.getItem('taxflow_current_page');
  setTimeout(()=>go(_lastPage||'dashboard'),400);
  scheduleIdleTask(()=>{
    updateAccountSelectors();
    recalcJournal();
    recalcPayroll();
    calcGratuity();
    bindDetailViews();
    bindEditActions();
    bindGenericAddActions();
    applyAllTableActions();
  },900);
}

if(!localStorage.getItem('taxflow_token')){
  window.location.replace('/login');
}else{
  // applyRoleBasedNav() calls /auth/me, a User-only endpoint — for an HRMS
  // sub-user (Employee principal) or a Branch Login Phase 2 session (Branch
  // principal) that 401s (no User row matches an "emp:"/"branch:" subject),
  // which authenticatedFetch correctly treats as an invalid session and
  // logs them straight back out. Skip it for both non-admin kinds;
  // applyHrmsPermissionNav() (hrms.html, via /auth/whoami) is the
  // employee-aware equivalent.
  var _principalKind=localStorage.getItem('taxflow_principal_kind');
  if(!['employee','branch'].includes(_principalKind)){
    applyRoleBasedNav().catch(()=>{});
  }else if(_principalKind==='branch'||!window.HRMS_STANDALONE){
    // Employee session on index.html (Main Dashboard Access phase), or any
    // Branch Login Phase 2 session (a Branch identity always lands on '/',
    // never '/hrms', and has zero HRMS access — applyMainDashboardPermissionNav()
    // is kind-agnostic and already handles this correctly with no changes
    // of its own, since a Branch principal's permissions never contain an
    // HR-suite key). hrms.html has its own separate call to
    // applyHrmsPermissionNav() in its own DOMContentLoaded handler for the
    // Employee-on-hrms.html case, this is index.html's equivalent.
    applyMainDashboardPermissionNav().catch(()=>{});
  }
  initApp();
}
